CREATE OR REPLACE FUNCTION "private"."befriend_group_members"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (select 1 from public.profiles p where p.id = new.user_id and p.is_placeholder) then
    return null;
  end if;

  insert into public.friendships (user_id, friend_id)
  select pair.a, pair.b
  from public.group_members m
  join public.profiles mp on mp.id = m.user_id and not mp.is_placeholder
  cross join lateral (
    values (new.user_id, m.user_id), (m.user_id, new.user_id)
  ) as pair (a, b)
  where m.group_id = new.group_id
    and m.user_id <> new.user_id
    and not exists (
      select 1 from public.blocks b
      where (b.blocker_id = new.user_id and b.blocked_id = m.user_id)
         or (b.blocker_id = m.user_id and b.blocked_id = new.user_id)
    )
  on conflict do nothing;

  return null;
end;
$$;


ALTER FUNCTION "private"."befriend_group_members"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."blocked_in_group"("gid" "uuid", "uid" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
      select 1 from public.blocks b
      join public.group_members m on m.group_id = gid and m.user_id = b.blocker_id
      where b.blocked_id = uid
    )
    or exists (
      select 1 from public.blocks b
      join public.group_members m on m.group_id = gid and m.user_id = b.blocked_id
      where b.blocker_id = uid
    );
$$;


