CREATE OR REPLACE FUNCTION "private"."check_expense_payers"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  eid uuid;
  amount bigint;
  total bigint;
begin
  if tg_table_name = 'expenses' then
    eid := new.id;
  elsif tg_op = 'DELETE' then
    eid := old.expense_id;
  else
    eid := new.expense_id;
  end if;

  select e.amount_cents into amount from public.expenses e where e.id = eid;
  if not found then
    return null;
  end if;

  select coalesce(sum(p.paid_cents), 0) into total
  from public.expense_payers p
  where p.expense_id = eid;

  if total <> amount then
    raise exception using
      message = 'payers_sum_mismatch',
      detail = format('Payers add up to %s but the expense is %s', total, amount),
      errcode = '23514';
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."check_expense_payers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."check_expense_splits"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  eid uuid;
  amount bigint;
  total bigint;
begin
  if tg_table_name = 'expenses' then
    eid := new.id;
  elsif tg_op = 'DELETE' then
    eid := old.expense_id;
  else
    eid := new.expense_id;
  end if;

  select e.amount_cents into amount from public.expenses e where e.id = eid;
  if not found then
    return null;
  end if;

  select coalesce(sum(s.share_cents), 0) into total
  from public.expense_splits s
  where s.expense_id = eid;

  if total <> amount then
    raise exception using
      message = 'splits_sum_mismatch',
      detail = format('Splits add up to %s but the expense is %s', total, amount),
      errcode = '23514';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."check_expense_splits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."check_group_has_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  gid uuid;
  owners int;
begin
  if tg_table_name = 'groups' then
    gid := new.id;
  elsif tg_op = 'DELETE' then
    gid := old.group_id;
  else
    gid := new.group_id;
  end if;

  if not exists (select 1 from public.groups g where g.id = gid) then
    return null;
  end if;

  select count(*) into owners
  from public.group_members m
  where m.group_id = gid and m.role = 'owner';

  if owners <> 1 then
    raise exception using
      message = 'group_owner_required',
      detail = 'A group must have exactly one owner',
      errcode = '23514';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "private"."check_group_has_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."check_payment"("gid" "uuid", "my_role" "public"."group_role", "payer" "uuid", "payee" "uuid", "amount" bigint) RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  uid uuid := auth.uid();
begin
  if amount is null or amount <= 0 or amount > 100000000000 then
    raise exception using message = 'invalid_amount', detail = 'Enter an amount greater than zero', errcode = '22023';
  end if;
  if payer is null or payee is null or payer = payee then
    raise exception using message = 'invalid_parties', detail = 'A payment needs two different people', errcode = '22023';
  end if;
  if my_role = 'member' and uid is distinct from payer and uid is distinct from payee then
    raise exception using
      message = 'not_a_party',
      detail = 'Only owners and admins can record a payment between two other people',
      errcode = '42501';
  end if;
  if (
    select count(*) from public.group_members m
    where m.group_id = gid and m.user_id in (payer, payee)
  ) <> 2 then
    raise exception using message = 'member_not_in_group', detail = 'Both people must be in the group', errcode = '23514';
  end if;
end;
$$;


ALTER FUNCTION "private"."check_payment"("gid" "uuid", "my_role" "public"."group_role", "payer" "uuid", "payee" "uuid", "amount" bigint) OWNER TO "postgres";


