CREATE OR REPLACE FUNCTION "private"."comments_notify"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  recipients uuid[];
begin
  if new.expense_id is not null then
    select array_agg(distinct u) into recipients
    from (
      select s.user_id as u from public.expense_splits s where s.expense_id = new.expense_id
      union
      select y.user_id from public.expense_payers y where y.expense_id = new.expense_id
      union
      select e.paid_by from public.expenses e where e.id = new.expense_id
      union
      select e.created_by from public.expenses e where e.id = new.expense_id
    ) x;
  elsif new.settlement_id is not null then
    select array_agg(distinct u) into recipients
    from (
      select s.from_user as u from public.settlements s where s.id = new.settlement_id
      union
      select s.to_user from public.settlements s where s.id = new.settlement_id
      union
      select s.created_by from public.settlements s where s.id = new.settlement_id
    ) x;
  else
    select array_agg(distinct u) into recipients
    from (
      select r.user_id as u from public.event_rsvps r
      where r.event_id = new.event_id and r.status in ('going', 'maybe')
      union
      select e.created_by from public.events e where e.id = new.event_id
    ) x;
  end if;

  perform private.notify(
    recipients,
    'comment.created',
    jsonb_build_object(
      'comment_id', new.id,
      'group_id', new.group_id,
      'expense_id', new.expense_id,
      'event_id', new.event_id,
      'settlement_id', new.settlement_id,
      'excerpt', left(new.body, 140)
    ),
    new.author_id
  );
  return null;
end;
$$;


ALTER FUNCTION "private"."comments_notify"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."comments_set_group"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if new.expense_id is not null then
    select e.group_id into new.group_id from public.expenses e where e.id = new.expense_id;
  elsif new.settlement_id is not null then
    select s.group_id into new.group_id from public.settlements s where s.id = new.settlement_id;
  else
    select ev.group_id into new.group_id from public.events ev where ev.id = new.event_id;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."comments_set_group"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."compute_split_rows"("amount" bigint, "kind" "public"."split_type", "splits" "jsonb") RETURNS TABLE("user_id" "uuid", "share_cents" bigint, "weight" numeric, "adjustment_cents" bigint)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uids uuid[];
  adjs bigint[];
  n int;
  rest bigint;
begin
  if kind is distinct from 'adjustment'::public.split_type then
    return query
      select c.user_id, c.share_cents, c.weight, null::bigint
      from private.compute_splits(amount, kind, splits) c;
    return;
  end if;

  if splits is null or jsonb_typeof(splits) <> 'array' or jsonb_array_length(splits) = 0 then
    raise exception using message = 'splits_required', detail = 'Add at least one person to the split', errcode = '22023';
  end if;

  begin
    select
      array_agg((e.elem ->> 'user_id')::uuid order by e.ord),
      array_agg(coalesce((e.elem ->> 'adjustment_cents')::bigint, 0) order by e.ord)
    into uids, adjs
    from jsonb_array_elements(splits) with ordinality as e (elem, ord);
  exception
    when invalid_text_representation or numeric_value_out_of_range or cannot_coerce then
      raise exception using message = 'invalid_splits', detail = 'The split is not valid', errcode = '22023';
  end;

  n := cardinality(uids);
  if array_position(uids, null) is not null then
    raise exception using message = 'invalid_splits', detail = 'Every split needs a person', errcode = '22023';
  end if;
  if (select count(distinct u) from unnest(uids) as u) <> n then
    raise exception using message = 'duplicate_user', detail = 'A person appears twice in the split', errcode = '22023';
  end if;
  if exists (select 1 from unnest(adjs) as a where abs(a) > 100000000000) then
    raise exception using message = 'invalid_splits', detail = 'An adjustment is too large', errcode = '22023';
  end if;

  rest := amount - (select sum(a) from unnest(adjs) as a);
  if rest < 0 then
    raise exception using
      message = 'adjustments_exceed_total',
      detail = format('Adjustments are %s more than the expense', -rest),
      errcode = '22023';
  end if;

  if exists (
    select 1
    from (
      select t.a, row_number() over (order by t.u) as rn
      from unnest(uids, adjs) as t (u, a)
    ) r
    where rest / n + case when r.rn <= rest % n then 1 else 0 end + r.a < 0
  ) then
    raise exception using message = 'negative_share', detail = 'An adjustment takes someone below zero', errcode = '22023';
  end if;

  return query
    select r.u, (rest / n + case when r.rn <= rest % n then 1 else 0 end + r.a)::bigint, null::numeric, r.a
    from (
      select t.u, t.a, t.ord, row_number() over (order by t.u) as rn
      from unnest(uids, adjs) with ordinality as t (u, a, ord)
    ) r
    order by r.ord;
end;
$$;


ALTER FUNCTION "private"."compute_split_rows"("amount" bigint, "kind" "public"."split_type", "splits" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."compute_splits"("amount" bigint, "kind" "public"."split_type", "splits" "jsonb") RETURNS TABLE("user_id" "uuid", "share_cents" bigint, "weight" numeric)
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uids uuid[];
  shares bigint[];
  weights numeric[];
  n int;
  explicit_n int;
  scaled numeric[];
  total_weight numeric;
  total_shares bigint;
begin
  if splits is null or jsonb_typeof(splits) <> 'array' or jsonb_array_length(splits) = 0 then
    raise exception using message = 'splits_required', detail = 'Add at least one person to the split', errcode = '22023';
  end if;

  begin
    select
      array_agg((e.elem ->> 'user_id')::uuid order by e.ord),
      array_agg((e.elem ->> 'share_cents')::bigint order by e.ord),
      array_agg((e.elem ->> 'weight')::numeric order by e.ord)
    into uids, shares, weights
    from jsonb_array_elements(splits) with ordinality as e (elem, ord);
  exception
    when invalid_text_representation or numeric_value_out_of_range or cannot_coerce then
      raise exception using message = 'invalid_splits', detail = 'The split is not valid', errcode = '22023';
  end;

  n := cardinality(uids);

  if array_position(uids, null) is not null then
    raise exception using message = 'invalid_splits', detail = 'Every split needs a person', errcode = '22023';
  end if;
  if (select count(distinct u) from unnest(uids) as u) <> n then
    raise exception using message = 'duplicate_user', detail = 'A person appears twice in the split', errcode = '22023';
  end if;

  select count(s), coalesce(sum(s), 0) into explicit_n, total_shares from unnest(shares) as s;

  if kind in ('exact', 'itemized') then
    if explicit_n <> n then
      raise exception using message = 'split_amount_required', detail = 'Enter an amount for each person', errcode = '22023';
    end if;
    if exists (select 1 from unnest(shares) as s where s < 0) then
      raise exception using message = 'invalid_splits', detail = 'Shares cannot be negative', errcode = '22023';
    end if;
    if total_shares <> amount then
      raise exception using
        message = 'splits_sum_mismatch',
        detail = format('Splits add up to %s but the expense is %s', total_shares, amount),
        errcode = '22023';
    end if;
    return query
      select t.u, t.s, t.w from unnest(uids, shares, weights) with ordinality as t (u, s, w, ord) order by t.ord;
    return;
  end if;

  if kind = 'equal' then
    weights := array_fill(1::numeric, array[n]);
  else
    if array_position(weights, null) is not null
       or exists (select 1 from unnest(weights) as w where w < 0) then
      raise exception using message = 'invalid_weight', detail = 'Enter a value for each person', errcode = '22023';
    end if;
  end if;

  -- Weights are fixed point with 6 decimals, like packages/core.
  scaled := array(select round(w * 1000000) from unnest(weights) as w);
  select sum(w) into total_weight from unnest(scaled) as w;

  if kind = 'percent' and total_weight <> 100000000 then
    raise exception using message = 'percent_sum', detail = 'Percentages must add up to 100', errcode = '22023';
  end if;
  if total_weight <= 0 then
    raise exception using message = 'zero_shares', detail = 'At least one person needs a share', errcode = '22023';
  end if;

  -- Largest remainder: floor(amount * w / sum) each, leftover cents to the
  -- largest remainders, ties by user id.
  return query
  with raw as (
    select
      t.u, t.w, t.sw, t.ord,
      div(amount::numeric * t.sw, total_weight)::bigint as base,
      mod(amount::numeric * t.sw, total_weight) as rem
    from unnest(uids, weights, scaled) with ordinality as t (u, w, sw, ord)
  ),
  ranked as (
    select r.*, row_number() over (order by r.rem desc, r.u) as rn,
           amount - sum(r.base) over () as leftover
    from raw r
  )
  select
    k.u,
    k.base + case when k.rn <= k.leftover then 1 else 0 end,
    case when kind = 'equal' then null else k.w end
  from ranked k
  order by k.ord;
end;
$$;


ALTER FUNCTION "private"."compute_splits"("amount" bigint, "kind" "public"."split_type", "splits" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."minor_units"("currency" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    RETURN CASE "upper"("currency") WHEN 'BIF'::"text" THEN 0 WHEN 'CLP'::"text" THEN 0 WHEN 'DJF'::"text" THEN 0 WHEN 'GNF'::"text" THEN 0 WHEN 'ISK'::"text" THEN 0 WHEN 'JPY'::"text" THEN 0 WHEN 'KMF'::"text" THEN 0 WHEN 'KRW'::"text" THEN 0 WHEN 'PYG'::"text" THEN 0 WHEN 'RWF'::"text" THEN 0 WHEN 'UGX'::"text" THEN 0 WHEN 'UYI'::"text" THEN 0 WHEN 'VND'::"text" THEN 0 WHEN 'VUV'::"text" THEN 0 WHEN 'XAF'::"text" THEN 0 WHEN 'XOF'::"text" THEN 0 WHEN 'XPF'::"text" THEN 0 WHEN 'BHD'::"text" THEN 3 WHEN 'IQD'::"text" THEN 3 WHEN 'JOD'::"text" THEN 3 WHEN 'KWD'::"text" THEN 3 WHEN 'LYD'::"text" THEN 3 WHEN 'OMR'::"text" THEN 3 WHEN 'TND'::"text" THEN 3 ELSE 2 END;


ALTER FUNCTION "private"."minor_units"("currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."convert_minor"("amount" bigint, "rate" numeric, "from_currency" "text", "to_currency" "text") RETURNS bigint
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    RETURN CASE WHEN ("from_currency" = "to_currency") THEN ("round"((("amount")::numeric * ("rate")::numeric(24,12))))::bigint ELSE ("round"(((("amount")::numeric * ("rate")::numeric(24,12)) * "power"((10)::numeric, (("private"."minor_units"("to_currency") - "private"."minor_units"("from_currency")))::numeric))))::bigint END;


ALTER FUNCTION "private"."convert_minor"("amount" bigint, "rate" numeric, "from_currency" "text", "to_currency" "text") OWNER TO "postgres";

