    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  n int;
begin
  update public.events e set status = 'done'
  where e.status = 'scheduled'
    and coalesce(e.ends_at, e.starts_at) < now();
  get diagnostics n = row_count;
