CREATE OR REPLACE FUNCTION "private"."pairwise_debts"("gid" "uuid") RETURNS TABLE("from_user" "uuid", "to_user" "uuid", "amount_cents" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  owed jsonb := '{}'::jsonb;
  e record;
  st record;
  cred_ids uuid[];
  cred_left numeric[];
  shares numeric[];
  rems numeric[];
  owes numeric;
  wsum numeric;
  leftover numeric;
  i int;
  j int;
begin
  -- Each expense's effect per person, exactly as group_balances: the converted total spread over
  -- the payers (credited) and over the split (debited), largest remainder, ties to the smaller id;
  -- a refund flips both. Expenses whose payers or split weigh nothing are skipped, as in core.
  for e in
    with expense_totals as (
      select x.id, case when x.is_refund then -1 else 1 end as sign,
        private.convert_minor(x.amount_cents, x.fx_rate, x.currency::text, g.currency::text) as total
      from public.expenses x
      join public.groups g on g.id = x.group_id
      where x.group_id = gid and x.deleted_at is null
        and (select sum(s.share_cents) from public.expense_splits s where s.expense_id = x.id) > 0
        and (select sum(y.paid_cents) from public.expense_payers y where y.expense_id = x.id) > 0
    ), split_parts as (
      select t.id, t.total, t.sign, s.user_id,
        div(t.total::numeric * s.share_cents::numeric, sum(s.share_cents) over w) as base,
        mod(t.total::numeric * s.share_cents::numeric, sum(s.share_cents) over w) as rem
      from expense_totals t
      join public.expense_splits s on s.expense_id = t.id
      window w as (partition by t.id)
    ), split_shares as (
      select p.id, p.user_id, p.sign,
        p.base + case
          when row_number() over (partition by p.id order by p.rem desc, p.user_id)
               <= p.total::numeric - sum(p.base) over (partition by p.id) then 1
          else 0
        end as share
      from split_parts p
    ), payer_parts as (
      select t.id, t.total, t.sign, y.user_id,
        div(t.total::numeric * y.paid_cents::numeric, sum(y.paid_cents) over w) as base,
        mod(t.total::numeric * y.paid_cents::numeric, sum(y.paid_cents) over w) as rem
      from expense_totals t
      join public.expense_payers y on y.expense_id = t.id
      window w as (partition by t.id)
    ), payer_shares as (
      select p.id, p.user_id, p.sign,
        p.base + case
          when row_number() over (partition by p.id order by p.rem desc, p.user_id)
               <= p.total::numeric - sum(p.base) over (partition by p.id) then 1
          else 0
        end as share
      from payer_parts p
    ), effects as (
      select d.id, d.user_id, sum(d.delta) as eff
      from (
        select x.id, x.user_id, x.sign * x.share as delta from payer_shares x
        union all
        select s.id, s.user_id, -s.sign * s.share from split_shares s
      ) d
      group by d.id, d.user_id
    )
    select f.id, array_agg(f.user_id order by f.user_id) as users, array_agg(f.eff order by f.user_id) as effs
    from effects f
    group by f.id
  loop
    -- Inside one expense the people who came out behind pay the people who came out ahead:
    -- debtors in id order, each spread over the creditors by what they are still owed.
    cred_ids := '{}';
    cred_left := '{}';
    for i in 1 .. cardinality(e.users) loop
      if e.effs[i] > 0 then
        cred_ids := cred_ids || e.users[i];
        cred_left := cred_left || e.effs[i];
      end if;
    end loop;

    for i in 1 .. cardinality(e.users) loop
      continue when e.effs[i] >= 0;
      owes := -e.effs[i];
      wsum := 0;
      for j in 1 .. coalesce(cardinality(cred_ids), 0) loop
        wsum := wsum + greatest(cred_left[j], 0);
      end loop;
      continue when wsum = 0;

      shares := array_fill(0::numeric, array[cardinality(cred_ids)]);
      rems := array_fill(-1::numeric, array[cardinality(cred_ids)]);
      leftover := owes;
      for j in 1 .. cardinality(cred_ids) loop
        if cred_left[j] > 0 then
          shares[j] := div(owes * cred_left[j], wsum);
          rems[j] := mod(owes * cred_left[j], wsum);
          leftover := leftover - shares[j];
        end if;
      end loop;
      -- Largest remainder first; creditors are in id order, so ties go to the smaller id.
      for j in
        select r.k from unnest(rems) with ordinality as r(rem, k)
        where r.rem >= 0
        order by r.rem desc, r.k
      loop
        exit when leftover = 0;
        shares[j] := shares[j] + 1;
        leftover := leftover - 1;
      end loop;

      for j in 1 .. cardinality(cred_ids) loop
        if shares[j] > 0 then
          cred_left[j] := cred_left[j] - shares[j];
          owed := private.add_pair_debt(owed, e.users[i], cred_ids[j], shares[j]);
        end if;
      end loop;
    end loop;
  end loop;

  -- Paying someone reduces what you owe them.
  for st in
    select s.from_user, s.to_user,
      private.convert_minor(s.amount_cents, s.fx_rate, s.currency::text, g.currency::text)::numeric as cents
    from public.settlements s
    join public.groups g on g.id = s.group_id
    where s.group_id = gid and s.deleted_at is null
  loop
    owed := private.add_pair_debt(owed, st.to_user, st.from_user, st.cents);
  end loop;

  return query
    select
      case when p.net > 0 then p.lo else p.hi end,
      case when p.net > 0 then p.hi else p.lo end,
      abs(p.net)::bigint
    from (
      select split_part(o.key, '|', 1)::uuid as lo, split_part(o.key, '|', 2)::uuid as hi,
        o.value::numeric as net
      from jsonb_each_text(owed) o
    ) p
    where p.net <> 0
    order by abs(p.net) desc, 1, 2;
end;
$$;


ALTER FUNCTION "private"."pairwise_debts"("gid" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."recurring_expenses" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "group_id" "uuid" NOT NULL,
    "description" "text" NOT NULL,
    "amount_cents" bigint NOT NULL,
    "currency" character(3) NOT NULL,
    "paid_by" "uuid" NOT NULL,
    "split_type" "public"."split_type" DEFAULT 'equal'::"public"."split_type" NOT NULL,
    "category" "text",
    "splits" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "recurrence" "public"."recurrence" NOT NULL,
    "next_run_on" "date" NOT NULL,
    "active" boolean DEFAULT true NOT NULL,
    "created_by" "uuid" DEFAULT "auth"."uid"(),
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "payers" "jsonb",
    "items" "jsonb",
    "tax_cents" bigint,
    "tip_cents" bigint,
    "discount_cents" bigint,
    "anchor_day" smallint,
    "notes" "text",
    CONSTRAINT "recurring_expenses_amount_cents_check" CHECK ((("amount_cents" > 0) AND ("amount_cents" <= '100000000000'::bigint))),
    CONSTRAINT "recurring_expenses_anchor_day_check" CHECK ((("anchor_day" >= 1) AND ("anchor_day" <= 31))),
    CONSTRAINT "recurring_expenses_category_check" CHECK (("char_length"("category") <= 40)),
    CONSTRAINT "recurring_expenses_currency_check" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "recurring_expenses_description_check" CHECK ((("char_length"("btrim"("description")) >= 1) AND ("char_length"("btrim"("description")) <= 120))),
    CONSTRAINT "recurring_expenses_discount_cents_check" CHECK ((("discount_cents" >= 0) AND ("discount_cents" <= '100000000000'::bigint))),
    CONSTRAINT "recurring_expenses_items_check" CHECK ((("items" IS NULL) OR (("jsonb_typeof"("items") = 'array'::"text") AND (("jsonb_array_length"("items") >= 1) AND ("jsonb_array_length"("items") <= 200))))),
    CONSTRAINT "recurring_expenses_notes_check" CHECK (("char_length"("notes") <= 2000)),
    CONSTRAINT "recurring_expenses_payers_check" CHECK ((("payers" IS NULL) OR ("jsonb_typeof"("payers") = 'array'::"text"))),
    CONSTRAINT "recurring_expenses_splits_check" CHECK (("jsonb_typeof"("splits") = 'array'::"text")),
    CONSTRAINT "recurring_expenses_tax_cents_check" CHECK ((("tax_cents" >= 0) AND ("tax_cents" <= '100000000000'::bigint))),
    CONSTRAINT "recurring_expenses_tip_cents_check" CHECK ((("tip_cents" >= 0) AND ("tip_cents" <= '100000000000'::bigint)))
);


ALTER TABLE "public"."recurring_expenses" OWNER TO "postgres";


COMMENT ON COLUMN "public"."recurring_expenses"."splits" IS 'Array of {user_id, share_cents?, weight?} in the create_expense payload format.';



COMMENT ON COLUMN "public"."recurring_expenses"."payers" IS 'Several payers as [{user_id, paid_cents}]; null means paid_by paid it all.';



COMMENT ON COLUMN "public"."recurring_expenses"."items" IS 'A by-item bill as entered: [{description, amount_cents, user_ids}], or null. splits then holds the shares worked out from it.';



COMMENT ON COLUMN "public"."recurring_expenses"."anchor_day" IS 'Day of the month monthly and yearly templates repeat on (short months clamp to their last day). Kept when only the interval changes. Null: the day of the first posted expense.';



COMMENT ON COLUMN "public"."recurring_expenses"."notes" IS 'Copied to every posted expense.';



CREATE OR REPLACE FUNCTION "private"."pause_recurring_for_departed"("r" "public"."recurring_expenses", "gone" "uuid"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  update public.recurring_expenses x set active = false where x.id = r.id;
  perform private.log_activity(r.group_id, null, 'recurring.paused', r.id, jsonb_build_object(
    'description', r.description,
    'reason', 'member_left',
    'user_ids', to_jsonb(gone)
  ));
  perform private.notify(
    array(
      select m.user_id from public.group_members m
      join public.profiles p on p.id = m.user_id and p.deleted_at is null
      where m.group_id = r.group_id
        and (m.user_id = r.created_by
             or (m.role in ('owner', 'admin')
                 and not exists (
                   select 1 from public.group_members c
                   join public.profiles cp on cp.id = c.user_id and cp.deleted_at is null
                   where c.group_id = r.group_id and c.user_id = r.created_by)))
    ),
    'recurring.paused',
    jsonb_build_object(
      'recurring_id', r.id,
      'group_id', r.group_id,
      'description', r.description,
      'user_ids', to_jsonb(gone)
    )
  );
end;
$$;


ALTER FUNCTION "private"."pause_recurring_for_departed"("r" "public"."recurring_expenses", "gone" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."pause_recurring_naming"("uid" "uuid", "gid" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  r public.recurring_expenses;
begin
  for r in
    select x.* from public.recurring_expenses x
    join public.groups g on g.id = x.group_id and g.archived_at is null
    where x.active
      and (gid is null or x.group_id = gid)
      and exists (select 1 from private.recurring_people(x) as people (u) where people.u = uid)
    order by x.group_id, x.id
    for update of x
  loop
    perform private.pause_recurring_for_departed(r, private.recurring_departed(r));
  end loop;
end;
$$;


ALTER FUNCTION "private"."pause_recurring_naming"("uid" "uuid", "gid" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."payment_currency"("requested" "text", "group_currency" "text") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  cur text := upper(coalesce(nullif(btrim(requested), ''), group_currency));
begin
  if cur !~ '^[A-Z]{3}$' then
    raise exception using message = 'invalid_currency', detail = 'Unknown currency code', errcode = '22023';
  end if;
  return cur;
end;
$_$;


