  if not private.valid_payment_handle(new.kind, new.handle) then
    raise exception using
      message = 'invalid_payment_handle',
      detail = 'That does not look like a handle for this app',
      errcode = '22023';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


