    SET "search_path" TO ''
    AS $$
declare
  note text := nullif(btrim(raw), '');
begin
  if char_length(note) > 500 then
    raise exception using message = 'note_too_long', detail = 'Keep the note under 500 characters', errcode = '22023';
  end if;
  return note;
end;
