    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if 'push' = any (new.channels) then
    perform private.invoke_edge_function(
      'notify',
      jsonb_build_object('id', new.id, 'user_id', new.user_id, 'type', new.type, 'data', new.data)
    );
  end if;
  return null;
end;
$$;


