    uid = created_by
    or uid = paid_by
    or coalesce(payers, '[]'::jsonb) @> jsonb_build_array(jsonb_build_object('user_id', uid))
    or coalesce(splits, '[]'::jsonb) @> jsonb_build_array(jsonb_build_object('user_id', uid))
  );
