  select r.paid_by
  union
  select private.try_uuid(e ->> 'user_id') from jsonb_array_elements(coalesce(r.payers, '[]'::jsonb)) e
  union
  select private.try_uuid(e ->> 'user_id') from jsonb_array_elements(r.splits) e;
$$;


