CREATE OR REPLACE FUNCTION "private"."settlements_notify_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  kind text;
begin
  if private.claiming() then
    return null;
  end if;
  if old.deleted_at is null and new.deleted_at is not null then
    kind := 'settlement.deleted';
  elsif old.deleted_at is not null and new.deleted_at is null then
    kind := 'settlement.restored';
  elsif new.deleted_at is null
    and (new.from_user, new.to_user, new.amount_cents, new.currency, new.settled_at)
        is distinct from
        (old.from_user, old.to_user, old.amount_cents, old.currency, old.settled_at) then
    kind := 'settlement.updated';
  else
    return null;
  end if;

  perform private.notify(
    array[old.from_user, old.to_user, new.from_user, new.to_user],
    kind,
    jsonb_build_object(
      'settlement_id', new.id,
      'group_id', new.group_id,
      'from_user', new.from_user,
      'to_user', new.to_user,
      'amount_cents', new.amount_cents,
      'currency', new.currency
    ),
    coalesce(auth.uid(), new.created_by)
  );
  return null;
end;
$$;


ALTER FUNCTION "private"."settlements_notify_change"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."shares_group_with"("other" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.group_members mine
    join public.group_members theirs on theirs.group_id = mine.group_id
    where mine.user_id = (select auth.uid()) and theirs.user_id = other
  );
$$;


ALTER FUNCTION "private"."shares_group_with"("other" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."skip_placeholder_notification"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- A placeholder only ever gets its invite.
  if new.type <> 'member.added'
     and exists (select 1 from public.profiles p where p.id = new.user_id and p.is_placeholder) then
    return null;
  end if;
  -- Its invite never goes to an address whose account has a block with whoever sent it. The
  -- seat remembers, so one goes out if that block is lifted.
  if new.type = 'member.added'
     and private.seat_email_blocked(new.user_id, private.try_uuid(new.data ->> 'actor_id')) then
    update public.placeholders x
    set held_by = private.try_uuid(new.data ->> 'actor_id'),
        held_reminder = coalesce((new.data ->> 'reminder')::boolean, false)
    where x.profile_id = new.user_id;
    return null;
  end if;
  -- Blocking mutes: nothing someone did reaches a person who blocked them.
  if exists (
    select 1 from public.blocks b
    where b.blocker_id = new.user_id
      and b.blocked_id = private.try_uuid(new.data ->> 'actor_id')
  ) then
    return null;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "private"."skip_placeholder_notification"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."spend_invite_budget"("uid" "uuid", "kind" "text", "gid" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform pg_advisory_xact_lock(hashtextextended('invite_sends:' || uid::text, 0));
  if (
    select count(*) from private.invite_sends s
    where s.sender = uid and s.sent_at > now() - interval '1 day'
  ) >= 20 then
    raise exception using message = 'too_many_invites', detail = 'That is a lot of invites for one day. Try again tomorrow', errcode = '23514';
  end if;
  insert into private.invite_sends (sender, kind, group_id) values (uid, kind, gid);
end;
$$;


