CREATE OR REPLACE FUNCTION "private"."sync_single_payer"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if (select count(*) from public.expense_payers p where p.expense_id = new.id) <= 1 then
    delete from public.expense_payers p where p.expense_id = new.id;
    insert into public.expense_payers (expense_id, user_id, paid_cents)
    values (new.id, new.paid_by, new.amount_cents);
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."sync_single_payer"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "private"."track_former_members"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    delete from private.former_members f
    where f.group_id = new.group_id and f.user_id = new.user_id;
    return null;
  end if;

  -- Rows removed by a cascading group or profile delete have nothing to point at, and a
  -- leaver nothing in the group names anymore has nothing to be read for.
  if exists (select 1 from public.groups g where g.id = old.group_id)
     and exists (select 1 from public.profiles p where p.id = old.user_id)
     and private.referenced_in_group(old.group_id, old.user_id) then
    insert into private.former_members (group_id, user_id)
    values (old.group_id, old.user_id)
    on conflict (group_id, user_id) do update set left_at = excluded.left_at;
  end if;
  return null;
end;
$$;


ALTER FUNCTION "private"."track_former_members"() OWNER TO "postgres";


