COMMENT ON COLUMN "public"."group_invites"."placeholder_id" IS 'Claim link: accepting it hands this placeholder (and its history) to the account (ADR 19).';



CREATE OR REPLACE FUNCTION "public"."create_invite"("group_id" "uuid", "role" "public"."group_role" DEFAULT 'member'::"public"."group_role", "max_uses" integer DEFAULT NULL::integer, "expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "email" "text" DEFAULT NULL::"text") RETURNS "public"."group_invites"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role := private.require_member(create_invite.group_id);
  g public.groups;
  inv public.group_invites;
  wanted public.group_role := coalesce(create_invite.role, 'member');
begin
  select * into g from public.groups x where x.id = create_invite.group_id;

  if g.is_direct then
    raise exception using message = 'direct_group', detail = 'Direct groups cannot have invites', errcode = '23514';
  end if;
  if g.archived_at is not null then
    raise exception using message = 'group_archived', detail = 'This group is archived', errcode = '23514';
  end if;
  if my_role = 'member' and not g.members_can_invite then
    raise exception using message = 'not_allowed', detail = 'Only admins can invite people to this group', errcode = '42501';
  end if;
  if wanted = 'owner' then
    raise exception using message = 'invalid_role', detail = 'Invites cannot make someone the owner', errcode = '22023';
  end if;
  if wanted = 'admin' and my_role <> 'owner' then
    raise exception using message = 'not_allowed', detail = 'Only the owner can invite admins', errcode = '42501';
  end if;
  if create_invite.max_uses is not null and create_invite.max_uses < 1 then
    raise exception using message = 'invalid_max_uses', detail = 'Max uses must be at least 1', errcode = '22023';
  end if;
  if create_invite.expires_at is not null and create_invite.expires_at <= now() then
    raise exception using message = 'invalid_expiry', detail = 'Expiry must be in the future', errcode = '22023';
  end if;

  insert into public.group_invites (group_id, role, max_uses, expires_at, email, created_by)
  values (
    create_invite.group_id,
    wanted,
    create_invite.max_uses,
    create_invite.expires_at,
    nullif(lower(btrim(create_invite.email)), ''),
    auth.uid()
  )
  returning * into inv;

  return inv;
end;
$$;


ALTER FUNCTION "public"."create_invite"("group_id" "uuid", "role" "public"."group_role", "max_uses" integer, "expires_at" timestamp with time zone, "email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_mfa_recovery_codes"() RETURNS SETOF "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  uid uuid := private.require_user();
  -- 32 symbols without 0, O, 1 and I, so a byte modulo 32 picks each one equally often.
  alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  bytes bytea;
  code text;
begin
  if coalesce(auth.jwt() ->> 'aal', 'aal1') <> 'aal2' then
    raise exception using
      message = 'mfa_required',
      detail = 'Recovery codes need a two-step sign in',
      errcode = '42501';
  end if;

  delete from private.mfa_recovery_codes where user_id = uid;
  for i in 1..10 loop
    bytes := extensions.gen_random_bytes(10);
    code := '';
    for j in 0..9 loop
      code := code || substr(alphabet, get_byte(bytes, j) % 32 + 1, 1);
    end loop;
    insert into private.mfa_recovery_codes (user_id, code_hash)
    values (uid, private.recovery_code_hash(code))
    on conflict do nothing;
    return next substr(code, 1, 5) || '-' || substr(code, 6, 5);
  end loop;
end;
$$;


ALTER FUNCTION "public"."create_mfa_recovery_codes"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_expense"("id" "uuid") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  gid uuid := (select x.group_id from public.expenses x where x.id = delete_expense.id);
  e public.expenses;
begin
  if gid is not null then
    perform 1 from public.groups g where g.id = gid for share;
    perform private.require_member(gid);
  end if;
  e := private.editable_expense(delete_expense.id);

  if e.deleted_at is null and exists (
    select s.user_id from public.expense_splits s where s.expense_id = e.id and s.share_cents > 0
    union
    select p.user_id from public.expense_payers p where p.expense_id = e.id
    union
    select e.paid_by
    except
    select m.user_id from public.group_members m where m.group_id = e.group_id
  ) then
    raise exception using message = 'split_member_not_in_group', detail = 'Someone in this expense has left the group', errcode = '23514';
  end if;

  update public.expenses x
  set deleted_at = coalesce(x.deleted_at, now())
  where x.id = e.id
  returning * into e;
  return e;
end;
$$;


ALTER FUNCTION "public"."delete_expense"("id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_group"("group_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role := private.require_member(delete_group.group_id);
begin
  if my_role <> 'owner' then
    raise exception using message = 'not_allowed', detail = 'Only the owner can delete the group', errcode = '42501';
  end if;
  perform 1 from public.groups g where g.id = delete_group.group_id for update;
  if exists (
    select 1 from public.group_balances b
    where b.group_id = delete_group.group_id and b.net_cents <> 0
  ) then
    raise exception using
      message = 'group_has_balances',
      detail = 'Settle every balance before deleting this group',
      errcode = '23514';
  end if;
  delete from public.groups g where g.id = delete_group.group_id;
end;
$$;


ALTER FUNCTION "public"."delete_group"("group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_my_account"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  uid uuid := auth.uid();
  owned record;
  heir uuid;
begin
  if uid is null then
    raise exception using message = 'not_authenticated', detail = 'You need to be signed in', errcode = '42501';
  end if;

  if exists (select 1 from public.profiles p where p.id = uid and p.deleted_at is not null) then
    return;
  end if;

  perform 1 from public.groups g
  where g.id in (select m.group_id from public.group_members m where m.user_id = uid)
  order by g.id
  for no key update;

  for owned in
    select m.group_id from public.group_members m where m.user_id = uid and m.role = 'owner'
  loop
    select m.user_id into heir
    from public.group_members m
    join public.profiles p on p.id = m.user_id
    where m.group_id = owned.group_id and m.user_id <> uid and p.deleted_at is null
      and not p.is_placeholder
    order by (m.role = 'admin') desc, m.joined_at, m.user_id
    limit 1;

    if heir is null then
      perform set_config('potluck.closing_account', 'on', true);
      delete from public.groups g where g.id = owned.group_id;
      perform set_config('potluck.closing_account', '', true);
    else
      update public.group_members m set role = 'member'
      where m.group_id = owned.group_id and m.user_id = uid;
      update public.group_members m set role = 'owner'
      where m.group_id = owned.group_id and m.user_id = heir;
    end if;
  end loop;

  delete from public.group_members m
  where m.user_id = uid
    and private.member_balance(m.group_id, uid) = 0;

  delete from public.push_tokens t where t.user_id = uid;
  delete from public.calendar_connections c where c.user_id = uid;
  delete from public.busy_blocks b where b.user_id = uid;
  delete from public.notifications n where n.user_id = uid;
  delete from public.availability a where a.user_id = uid;
  delete from public.availability_requests r where r.user_id = uid;
  delete from public.event_rsvps r where r.user_id = uid;
  delete from public.friendships f where f.user_id = uid or f.friend_id = uid;
  perform set_config('potluck.closing_account', 'on', true);
  delete from public.blocks b where b.blocker_id = uid or b.blocked_id = uid;
  perform set_config('potluck.closing_account', '', true);

  update public.group_invites i set revoked_at = now()
  where i.created_by = uid and i.revoked_at is null;

  update public.profiles p set
    display_name = 'Former member',
    avatar_path = null,
    timezone = 'UTC',
    locale = 'en',
    deleted_at = now()
  where p.id = uid;

  perform private.pause_recurring_naming(uid);
end;
$$;


ALTER FUNCTION "public"."delete_my_account"() OWNER TO "postgres";


