CREATE OR REPLACE FUNCTION "public"."friend_activity"("friend" "uuid", "before_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "before_id" "uuid" DEFAULT NULL::"uuid", "max_rows" integer DEFAULT 30) RETURNS TABLE("id" "uuid", "group_id" "uuid", "actor_id" "uuid", "verb" "text", "subject_id" "uuid", "data" "jsonb", "created_at" timestamp with time zone, "actor_info" "jsonb", "group_info" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  gids uuid[] := array(select private.my_group_ids());
  lim int := least(greatest(coalesce(friend_activity.max_rows, 30), 1), 100);
begin
  if friend_activity.friend is null or friend_activity.friend = uid then
    raise exception using message = 'invalid_friend', detail = 'Pick someone other than yourself', errcode = '22023';
  end if;
  if (friend_activity.before_at is null) <> (friend_activity.before_id is null) then
    raise exception using message = 'invalid_cursor', detail = 'A page cursor needs a time and an id', errcode = '22023';
  end if;

  -- Both people paid for (expense_payers) or share in the expense (for expense entries and
  -- comments on one), the payment is between them (and comments on it), or it happened in their
  -- one-to-one tab.
  return query
  select
    a.id,
    a.group_id,
    a.actor_id,
    a.verb,
    a.subject_id,
    a.data,
    a.created_at,
    case when p.id is null then null else
      jsonb_build_object('id', p.id, 'display_name', p.display_name, 'avatar_path', p.avatar_path)
    end,
    jsonb_build_object('id', g.id, 'name', g.name, 'emoji', g.emoji, 'is_direct', g.is_direct)
  from public.activity a
  join public.groups g on g.id = a.group_id
  left join public.profiles p on p.id = a.actor_id
  where a.group_id = any (gids)
    and (
      friend_activity.before_id is null
      or (a.created_at, a.id) < (friend_activity.before_at, friend_activity.before_id)
    )
    and (
      (
        -- Their one-to-one tab, minus the bookkeeping of setting it up.
        g.is_direct
        and a.verb not like 'member.%'
        and a.verb not like 'group.%'
        and exists (
          select 1 from public.group_members m
          where m.group_id = g.id and m.user_id = friend_activity.friend
        )
      )
      or (
        (a.verb like 'settlement.%' or (a.verb = 'comment.created' and a.data ? 'settlement_id'))
        and exists (
          select 1 from public.settlements st
          where st.id = case
              when a.verb = 'comment.created' then private.try_uuid(a.data ->> 'settlement_id')
              else a.subject_id
            end
            and (
              (st.from_user = uid and st.to_user = friend_activity.friend)
              or (st.from_user = friend_activity.friend and st.to_user = uid)
            )
        )
      )
      or (
        (a.verb like 'expense.%' or (a.verb = 'comment.created' and a.data ? 'expense_id'))
        and exists (
          select 1
          from public.expenses e
          where e.id = case
              when a.verb = 'comment.created' then private.try_uuid(a.data ->> 'expense_id')
              else a.subject_id
            end
            and (
              exists (select 1 from public.expense_payers x where x.expense_id = e.id and x.user_id = uid)
              or exists (select 1 from public.expense_splits s where s.expense_id = e.id and s.user_id = uid)
            )
            and (
              exists (
                select 1 from public.expense_payers x
                where x.expense_id = e.id and x.user_id = friend_activity.friend
              )
              or exists (
                select 1 from public.expense_splits s
                where s.expense_id = e.id and s.user_id = friend_activity.friend
              )
            )
        )
      )
    )
  order by a.created_at desc, a.id desc
  limit lim;
end;
$$;


ALTER FUNCTION "public"."friend_activity"("friend" "uuid", "before_at" timestamp with time zone, "before_id" "uuid", "max_rows" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."friend_activity"("friend" "uuid", "before_at" timestamp with time zone, "before_id" "uuid", "max_rows" integer) IS 'Feed entries that involve both the viewer and a friend, newest first.';



CREATE OR REPLACE FUNCTION "public"."friend_balances"() RETURNS TABLE("friend_id" "uuid", "group_id" "uuid", "currency" "text", "net_cents" bigint, "archived" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  g record;
begin
  for g in
    select x.id, x.currency, x.archived_at
    from public.groups x
    join public.group_members m on m.group_id = x.id and m.user_id = uid
    order by x.id
  loop
    return query
      select
        case when d.from_user = uid then d.to_user else d.from_user end,
        g.id,
        g.currency::text,
        case when d.from_user = uid then -d.amount_cents else d.amount_cents end,
        g.archived_at is not null
      from private.group_debts(g.id) d
      where uid in (d.from_user, d.to_user)
        and exists (
          select 1 from public.group_members f
          where f.group_id = g.id
            and f.user_id = case when d.from_user = uid then d.to_user else d.from_user end
        );
  end loop;
end;
$$;


ALTER FUNCTION "public"."friend_balances"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."friend_invite_preview"("code" "text") RETURNS TABLE("name" "text", "avatar_path" "text", "status" "text", "is_friend" boolean, "is_self" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  inv public.friend_invites;
  uid uuid := auth.uid();
begin
  select * into inv from public.friend_invites i where i.code = friend_invite_preview.code;
  if inv.id is null then
    raise exception using message = 'invite_not_found', detail = 'This invite link is not valid', errcode = 'PT404';
  end if;

  return query
  with preview as (
    select
      p.id,
      p.display_name,
      p.avatar_path,
      exists (select 1 from public.friendships f where f.user_id = uid and f.friend_id = p.id) as friends,
      case
        when p.deleted_at is not null or inv.revoked_at is not null then 'revoked'
        when uid is not null and private.has_block(uid, p.id) then 'revoked'
        when uid is not null and (uid = p.id or exists (
          select 1 from public.friendships f where f.user_id = uid and f.friend_id = p.id
        )) then 'valid'
        when inv.expires_at is not null and inv.expires_at <= now() then 'expired'
        when inv.max_uses is not null and inv.uses >= inv.max_uses then 'used_up'
        else 'valid'
      end as status
    from public.profiles p
    where p.id = inv.created_by
  )
  -- Only a live link says who it is from.
  select
    case when pv.status = 'valid' then split_part(pv.display_name, ' ', 1) end,
    case when pv.status = 'valid' then pv.avatar_path end,
    pv.status,
    uid is not null and pv.status = 'valid' and pv.friends,
    uid is not null and pv.status = 'valid' and uid = pv.id
  from preview pv;
end;
$$;


ALTER FUNCTION "public"."friend_invite_preview"("code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_direct_group"("friend_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  gid uuid;
begin
  if get_or_create_direct_group.friend_id = uid then
    raise exception using message = 'invalid_friend', detail = 'You cannot split with yourself', errcode = '22023';
  end if;

  if not exists (
    select 1 from public.profiles p
    where p.id = get_or_create_direct_group.friend_id
      and p.deleted_at is null
      and not p.is_placeholder
      and p.id in (select private.my_contact_ids())
  ) or private.has_block(uid, get_or_create_direct_group.friend_id) then
    raise exception using message = 'not_a_friend', detail = 'You can only split with friends', errcode = '42501';
  end if;

  -- Serialize creation per pair so two taps do not create two groups.
  perform pg_advisory_xact_lock(hashtextextended(
    least(uid::text, get_or_create_direct_group.friend_id::text)
      || greatest(uid::text, get_or_create_direct_group.friend_id::text),
    0
  ));

  select g.id into gid
  from public.groups g
  where g.is_direct
    and exists (select 1 from public.group_members m where m.group_id = g.id and m.user_id = uid)
    and exists (
      select 1 from public.group_members m
      where m.group_id = g.id and m.user_id = get_or_create_direct_group.friend_id
    )
  order by g.created_at
  limit 1;

  if gid is not null then
    return gid;
  end if;

  insert into public.groups (name, currency, is_direct, members_can_invite, created_by)
  select 'Direct', p.default_currency, true, false, uid
  from public.profiles p where p.id = uid
  returning id into gid;

  insert into public.group_members (group_id, user_id, role)
  values (gid, uid, 'owner'), (gid, get_or_create_direct_group.friend_id, 'admin');

  return gid;
end;
$$;


ALTER FUNCTION "public"."get_or_create_direct_group"("friend_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guest_link_preview"("code" "text", "token" "text" DEFAULT NULL::"text") RETURNS TABLE("status" "text", "title" "text", "emoji" "text", "group_emoji" "text", "host_name" "text", "timezone" "text", "window_start" "date", "window_end" "date", "day_start_minute" integer, "day_end_minute" integer, "slot_minutes" integer, "duration_minutes" integer, "expires_at" timestamp with time zone, "max_guests" integer, "guest_count" integer, "respondents" integer, "my_name" "text", "my_slots" "jsonb", "heat" "jsonb", "starts_at" timestamp with time zone, "ends_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  link public.event_guest_links;
  ev public.events;
  grp public.groups;
  me public.event_guests;
  answered boolean;
  guests int;
  host text;
  st text;
begin
  select * into link from public.event_guest_links l where l.code = guest_link_preview.code;
  if link.id is null then
    raise exception using message = 'guest_link_not_found', detail = 'This guest link is not valid', errcode = 'PT404';
  end if;
  select * into ev from public.events e where e.id = link.event_id;
  select * into grp from public.groups g where g.id = link.group_id;
  me := private.guest_for_token(link.id, guest_link_preview.token);
  answered := me.id is not null and me.removed_at is null;
  select count(*)::int into guests from public.event_guests g
  where g.link_id = link.id and g.removed_at is null;
  select nullif(split_part(p.display_name, ' ', 1), '') into host
  from public.profiles p where p.id = link.created_by and p.deleted_at is null;

  st := case
    when link.revoked_at is not null then 'revoked'
    when grp.archived_at is not null then 'archived'
    when me.removed_at is not null then 'removed'
    when ev.status in ('scheduled', 'done') and answered then 'scheduled'
    when link.expires_at <= now() then 'expired'
    when ev.status <> 'polling' then 'closed'
    when not answered and guests >= link.max_guests then 'full'
    else 'open'
  end;

  if st = 'scheduled' then
    return query select st, ev.title, ev.emoji, grp.emoji, host, ev.timezone,
      null::date, null::date, null::int, null::int, null::int, null::int,
      null::timestamptz, null::int, null::int, null::int,
      me.display_name, null::jsonb, null::jsonb,
      ev.starts_at, ev.ends_at;
    return;
  end if;

  if st not in ('open', 'full') then
    return query select st, null::text, null::text, null::text, null::text, null::text,
      null::date, null::date, null::int, null::int, null::int, null::int,
      null::timestamptz, null::int, null::int, null::int, null::text, null::jsonb, null::jsonb,
      null::timestamptz, null::timestamptz;
    return;
  end if;

  return query
  with answers as (
    select a.user_id as who, a.slot_start, a.level
    from public.availability a
    join public.group_members m on m.group_id = ev.group_id and m.user_id = a.user_id
    where a.event_id = ev.id
    union all
    select ga.guest_id, ga.slot_start, ga.level
    from public.event_guest_availability ga
    join public.event_guests g on g.id = ga.guest_id and g.removed_at is null
    where ga.event_id = ev.id
  )
  select
    st,
    ev.title,
    ev.emoji,
    grp.emoji,
    host,
    ev.timezone,
    ev.window_start,
    ev.window_end,
    ev.day_start_minute,
    ev.day_end_minute,
    ev.slot_minutes,
    ev.duration_minutes,
    link.expires_at,
    link.max_guests,
    guests,
    case when st = 'open' then (select count(distinct x.who)::int from answers x) end,
    case when answered then me.display_name end,
    case when answered then (
      select coalesce(jsonb_agg(jsonb_build_object('slot_start', ga.slot_start, 'level', ga.level) order by ga.slot_start), '[]'::jsonb)
      from public.event_guest_availability ga where ga.guest_id = me.id
    ) end,
    case when st = 'open' then (
      select coalesce(jsonb_agg(jsonb_build_object('slot_start', h.slot_start, 'yes', h.yes, 'maybe', h.maybe) order by h.slot_start), '[]'::jsonb)
      from (
        select
          x.slot_start,
          (count(*) filter (where x.level = 'yes'))::int as yes,
          (count(*) filter (where x.level = 'maybe'))::int as maybe
        from answers x
        group by x.slot_start
      ) h
    ) end,
    null::timestamptz,
    null::timestamptz;
end;
$$;


ALTER FUNCTION "public"."guest_link_preview"("code" "text", "token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_preview"("code" "text") RETURNS TABLE("group_id" "uuid", "name" "text", "emoji" "text", "color" "text", "cover_path" "text", "member_count" integer, "first_names" "text"[], "status" "text", "is_member" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  inv public.group_invites;
  uid uuid := auth.uid();
begin
  select * into inv from public.group_invites i where i.code = invite_preview.code;

  if inv.id is null then
    raise exception using message = 'invite_not_found', detail = 'This invite link is not valid', errcode = 'PT404';
  end if;

  return query
  select
    g.id,
    g.name,
    g.emoji,
    g.color,
    g.cover_path,
    (
      select count(*)::int from public.group_members m
      join public.profiles p on p.id = m.user_id
      where m.group_id = g.id and not p.is_placeholder
    ),
    array(
      select split_part(p.display_name, ' ', 1)
      from public.group_members m
      join public.profiles p on p.id = m.user_id
      where m.group_id = g.id and p.deleted_at is null and not p.is_placeholder
      order by (m.role = 'owner') desc, m.joined_at, p.id
      limit 5
    ),
    case
      when inv.revoked_at is not null then 'revoked'
      when uid is not null and not x.is_member and private.blocked_in_group(g.id, uid) then 'revoked'
      when inv.expires_at is not null and inv.expires_at <= now() then 'expired'
      when inv.max_uses is not null and inv.uses >= inv.max_uses then 'used_up'
      when g.archived_at is not null then 'archived'
      else 'valid'
    end,
    x.is_member
  from public.groups g
  cross join lateral (
    select exists (
      select 1 from public.group_members m
      where m.group_id = g.id and m.user_id = uid
    ) as is_member
  ) x
  where g.id = inv.group_id;
end;
$$;


ALTER FUNCTION "public"."invite_preview"("code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."invite_preview_v2"("code" "text") RETURNS TABLE("group_id" "uuid", "name" "text", "emoji" "text", "color" "text", "cover_path" "text", "member_count" integer, "first_names" "text"[], "status" "text", "is_member" boolean, "placeholder_name" "text", "email_hint" "text", "email_matches" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  inv public.group_invites;
  uid uuid := auth.uid();
  my_email text;
begin
  select * into inv from public.group_invites i where i.code = invite_preview_v2.code;

  if inv.id is null then
    raise exception using message = 'invite_not_found', detail = 'This invite link is not valid', errcode = 'PT404';
  end if;

  if uid is not null then
    select private.ascii_lower(u.email) into my_email from auth.users u where u.id = uid;
  end if;

  return query
  with preview as (
    select
      g.id,
      g.name,
      g.emoji,
      g.color,
      g.cover_path,
      (
        select count(*)::int from public.group_members m
        join public.profiles p on p.id = m.user_id
        where m.group_id = g.id and not p.is_placeholder
      ) as member_count,
      array(
        select split_part(p.display_name, ' ', 1)
        from public.group_members m
        join public.profiles p on p.id = m.user_id
        where m.group_id = g.id and p.deleted_at is null and not p.is_placeholder
        order by (m.role = 'owner') desc, m.joined_at, p.id
        limit 5
      ) as first_names,
      case
        when x.is_member then 'valid'
        -- A block reads like a revoked link: nobody learns they were blocked.
        when inv.revoked_at is not null
          or (uid is not null and private.blocked_in_group(g.id, uid)) then 'revoked'
        when inv.expires_at is not null and inv.expires_at <= now() then 'expired'
        when inv.max_uses is not null and inv.uses >= inv.max_uses then 'used_up'
        when inv.placeholder_id is not null and not exists (
          select 1 from public.group_members m where m.group_id = g.id and m.user_id = inv.placeholder_id
        ) then 'revoked'
        when g.archived_at is not null and inv.placeholder_id is null then 'archived'
        else 'valid'
      end as status,
      x.is_member
    from public.groups g
    cross join lateral (
      select exists (
        select 1 from public.group_members m
        where m.group_id = g.id and m.user_id = uid
      ) as is_member
    ) x
    where g.id = inv.group_id
  )
  select
    pv.id,
    pv.name,
    pv.emoji,
    pv.color,
    pv.cover_path,
    pv.member_count,
    pv.first_names,
    pv.status,
    pv.is_member,
    -- Only a live claim link says whose seat it is.
    case when pv.status = 'valid' and not pv.is_member then
      (select split_part(p.display_name, ' ', 1) from public.profiles p where p.id = inv.placeholder_id)
    end,
    case when pv.status = 'valid' and not pv.is_member then
      (select ph.email_hint from public.placeholders ph where ph.profile_id = inv.placeholder_id)
    end,
    case when pv.status = 'valid' and not pv.is_member and inv.email is not null and my_email is not null
      then my_email = inv.email
    end
  from preview pv;
end;
$$;


ALTER FUNCTION "public"."invite_preview_v2"("code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."leave_group"("group_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role;
  uid uuid := auth.uid();
  others_active int;
begin
  perform 1 from public.groups g where g.id = leave_group.group_id for no key update;
  my_role := private.require_member(leave_group.group_id);

  select count(*) into others_active
  from public.group_members m
  join public.profiles p on p.id = m.user_id
  where m.group_id = leave_group.group_id and m.user_id <> uid and p.deleted_at is null
    and not p.is_placeholder;

  if my_role = 'owner' and others_active = 0 then
    if exists (
      select 1 from public.group_balances b
      join public.profiles p on p.id = b.user_id
      where b.group_id = leave_group.group_id
        and b.user_id <> uid
        and p.deleted_at is null
        and b.net_cents <> 0
    ) then
      raise exception using message = 'member_has_balance', detail = 'Someone here still has an unsettled balance', errcode = '23514';
    end if;
    -- Whatever is left is between the owner and closed accounts, which nobody
    -- can settle anymore; the delete guard allows this like closing an account.
    perform set_config('potluck.closing_account', 'on', true);
    delete from public.groups g where g.id = leave_group.group_id;
    perform set_config('potluck.closing_account', '', true);
    return;
  end if;

  if private.member_balance(leave_group.group_id, uid) <> 0 then
    raise exception using message = 'member_has_balance', detail = 'Settle up before leaving this group', errcode = '23514';
  end if;

  if my_role = 'owner' then
    raise exception using message = 'owner_must_transfer', detail = 'Transfer ownership before leaving', errcode = '23514';
  end if;

  delete from public.group_members m
  where m.group_id = leave_group.group_id and m.user_id = uid;
end;
$$;


ALTER FUNCTION "public"."leave_group"("group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."make_expense_recurring"("expense_id" "uuid", "recurrence" "public"."recurrence") RETURNS "public"."recurring_expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  eid uuid := make_expense_recurring.expense_id;
  kind public.recurrence := make_expense_recurring.recurrence;
  my_role public.group_role;
  gid uuid;
  e public.expenses;
  v_splits jsonb;
  v_items jsonb;
  v_payers jsonb;
  result public.recurring_expenses;
begin
  if kind is null then
    raise exception using message = 'invalid_payload', detail = 'Pick how often it repeats', errcode = '22023';
  end if;
  select x.group_id into gid from public.expenses x where x.id = eid;
  if gid is null then
    raise exception using message = 'expense_not_found', detail = 'Expense not found', errcode = 'PT404';
  end if;
  perform 1 from public.groups x where x.id = gid for share;
  my_role := private.require_member(gid);
  perform private.require_unarchived(gid);

  select * into e from public.expenses x where x.id = eid for update;
  if my_role = 'member' and uid is distinct from e.created_by and uid is distinct from e.paid_by
     and not exists (select 1 from public.expense_payers x where x.expense_id = e.id and x.user_id = uid) then
    raise exception using message = 'not_allowed', detail = 'You can only edit your own expenses', errcode = '42501';
  end if;
  if e.deleted_at is not null then
    raise exception using message = 'expense_deleted', detail = 'Restore this expense before editing it', errcode = '23514';
  end if;
  if e.recurring_id is not null then
    raise exception using message = 'already_recurring', detail = 'This expense already repeats', errcode = '23514';
  end if;
  if e.is_refund then
    raise exception using message = 'invalid_payload', detail = 'A refund cannot repeat', errcode = '22023';
  end if;
  if exists (
    select 1 from (
      select x.user_id from public.expense_payers x where x.expense_id = e.id
      union
      select x.user_id from public.expense_splits x where x.expense_id = e.id and x.share_cents > 0
    ) people
    where not exists (select 1 from public.group_members m where m.group_id = gid and m.user_id = people.user_id)
       or exists (select 1 from public.profiles p where p.id = people.user_id and p.deleted_at is not null)
  ) then
    raise exception using message = 'split_member_not_in_group', detail = 'Someone in this expense has left the group', errcode = '23514';
  end if;

  -- The split in the create_expense payload format, from the stored rows.
  select jsonb_agg(case
      when e.split_type = 'equal' then jsonb_build_object('user_id', s.user_id)
      when e.split_type in ('percent', 'shares') then jsonb_build_object('user_id', s.user_id, 'weight', s.weight)
      when e.split_type = 'adjustment' then
        jsonb_build_object('user_id', s.user_id, 'adjustment_cents', coalesce(s.adjustment_cents, 0))
      else jsonb_build_object('user_id', s.user_id, 'share_cents', s.share_cents)
    end order by s.user_id)
  into v_splits
  from public.expense_splits s
  where s.expense_id = e.id
    and (e.split_type not in ('exact', 'itemized') or s.share_cents > 0);

  if e.split_type = 'itemized' then
    select jsonb_agg(jsonb_build_object('description', i.description, 'amount_cents', i.amount_cents,
             'user_ids', to_jsonb(i.user_ids)) order by i.position)
    into v_items
    from public.expense_items i where i.expense_id = e.id;
  end if;

  select case when count(*) > 1 then
      jsonb_agg(jsonb_build_object('user_id', x.user_id, 'paid_cents', x.paid_cents) order by x.user_id)
    end
  into v_payers
  from public.expense_payers x where x.expense_id = e.id;

  insert into public.recurring_expenses (
    group_id, description, amount_cents, currency, paid_by, payers, split_type, category,
    splits, items, tax_cents, tip_cents, discount_cents, recurrence, next_run_on, anchor_day,
    notes, created_by
  ) values (
    gid, e.description, e.amount_cents, e.currency, e.paid_by, v_payers, e.split_type, e.category,
    v_splits, v_items,
    case when v_items is not null then e.tax_cents end,
    case when v_items is not null then e.tip_cents end,
    case when v_items is not null then e.discount_cents end,
    kind,
    -- Not before the caller's own today, the day the app previews.
    private.recurring_next_from(e.spent_at, kind, extract(day from e.spent_at)::int, private.local_today(uid)),
    extract(day from e.spent_at)::smallint,
    e.notes,
    uid
  )
  returning * into result;

  update public.expenses x set recurring_id = result.id where x.id = e.id;

  perform private.log_activity(gid, uid, 'recurring.created', result.id, jsonb_build_object(
    'description', result.description,
    'amount_cents', result.amount_cents,
    'currency', result.currency,
    'recurrence', result.recurrence,
    'next_run_on', result.next_run_on,
    'expense_id', e.id
  ));
  return result;
end;
$$;


ALTER FUNCTION "public"."make_expense_recurring"("expense_id" "uuid", "recurrence" "public"."recurrence") OWNER TO "postgres";


