    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform private.notify(array[target], 'account.mfa_removed', '{}'::jsonb, null);
end;
$$;


ALTER FUNCTION "public"."notify_mfa_recovered"("target" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_mfa_recover_attempt"("target" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  recent int;
begin
  perform pg_advisory_xact_lock(hashtextextended('mfa_recover:' || target::text, 0));
  delete from private.mfa_recover_attempts a
  where a.user_id = target and a.attempted_at < now() - interval '1 day';
  select count(*) into recent from private.mfa_recover_attempts a
  where a.user_id = target and a.attempted_at > now() - interval '15 minutes';
  if recent >= 5 then
    return false;
  end if;
  insert into private.mfa_recover_attempts (user_id) values (target);
  return true;
end;
$$;


ALTER FUNCTION "public"."record_mfa_recover_attempt"("target" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."debt_reminders" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "group_id" "uuid" NOT NULL,
    "from_user" "uuid" NOT NULL,
    "to_user" "uuid" NOT NULL,
    "amount_cents" bigint NOT NULL,
    "currency" character(3) NOT NULL,
    "note" "text",
    "sent_on" "date" DEFAULT (("now"() AT TIME ZONE 'UTC'::"text"))::"date" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "debt_reminders_amount_cents_check" CHECK (("amount_cents" > 0)),
    CONSTRAINT "debt_reminders_check" CHECK (("from_user" <> "to_user")),
    CONSTRAINT "debt_reminders_note_check" CHECK (("char_length"("note") <= 280))
);


ALTER TABLE "public"."debt_reminders" OWNER TO "postgres";


COMMENT ON TABLE "public"."debt_reminders" IS 'One row per reminder sent; the unique key keeps it to once a day per pair.';



CREATE OR REPLACE FUNCTION "public"."remind_debt"("group_id" "uuid", "user_id" "uuid", "note" "text" DEFAULT NULL::"text") RETURNS "public"."debt_reminders"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  g public.groups;
  owed bigint;
  v_note text := nullif(btrim(remind_debt.note), '');
  result public.debt_reminders;
begin
  perform private.require_member(remind_debt.group_id);
  perform private.require_group_open(remind_debt.group_id);
  select * into g from public.groups x where x.id = remind_debt.group_id;

  if char_length(v_note) > 280 then
    raise exception using message = 'note_too_long', detail = 'Keep the note short', errcode = '22023';
  end if;
  if remind_debt.user_id is null or remind_debt.user_id = uid then
    raise exception using message = 'invalid_parties', detail = 'Pick someone who owes you', errcode = '22023';
  end if;
  if not exists (
    select 1 from public.group_members m
    where m.group_id = g.id and m.user_id = remind_debt.user_id
  ) then
    raise exception using message = 'member_not_in_group', detail = 'They are not in this group', errcode = '23514';
  end if;

  select d.amount_cents into owed
  from private.group_debts(g.id) d
  where d.from_user = remind_debt.user_id and d.to_user = uid;
  if coalesce(owed, 0) <= 0 then
    raise exception using message = 'nothing_owed', detail = 'They do not owe you anything here', errcode = '23514';
  end if;

  insert into public.debt_reminders (group_id, from_user, to_user, amount_cents, currency, note)
  values (g.id, uid, remind_debt.user_id, owed, g.currency, v_note)
  on conflict on constraint debt_reminders_once_a_day do nothing
  returning * into result;
  if result.id is null then
    raise exception using message = 'already_reminded', detail = 'You already sent a reminder today', errcode = '23514';
  end if;

  perform private.notify(
    array[remind_debt.user_id],
    'debt.reminder',
    jsonb_build_object(
      'group_id', g.id,
      'from_user', uid,
      'amount_cents', owed,
      'currency', g.currency,
      'note', v_note
    ),
    uid
  );
  return result;
end;
$$;


ALTER FUNCTION "public"."remind_debt"("group_id" "uuid", "user_id" "uuid", "note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remind_placeholder"("user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  ph public.placeholders;
begin
  select * into ph from public.placeholders x where x.profile_id = remind_placeholder.user_id;
  if ph.profile_id is null then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;
  perform private.require_member(ph.group_id);
  perform private.require_group_open(ph.group_id);
  if not exists (select 1 from public.group_members m where m.group_id = ph.group_id and m.user_id = ph.profile_id) then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;
  if ph.email is null then
    raise exception using message = 'placeholder_no_email', detail = 'Add an email address to send an invite', errcode = '23514';
  end if;
  if ph.reminded_at is not null then
    raise exception using message = 'placeholder_already_reminded', detail = 'A reminder was already sent', errcode = '23514';
  end if;

  perform private.spend_invite_budget(uid, 'reminder', ph.group_id);
  update public.placeholders x set reminded_at = now() where x.profile_id = ph.profile_id;

  -- Across a block the reminder is spent like any other, and nothing is sent: the notifications
  -- trigger holds it back until the block goes.
  perform private.notify(
    array[ph.profile_id],
    'member.added',
    jsonb_build_object('group_id', ph.group_id, 'role', 'member', 'reminder', true),
    uid
  );
end;
$$;


ALTER FUNCTION "public"."remind_placeholder"("user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_friend"("friend_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
begin
  if exists (
    select 1 from public.groups g
    join public.group_members a on a.group_id = g.id and a.user_id = uid
    join public.group_members b on b.group_id = g.id and b.user_id = remove_friend.friend_id
    where g.is_direct and private.member_balance(g.id, uid) <> 0
  ) then
    raise exception using message = 'friend_has_balance', detail = 'Settle up before removing this friend', errcode = '23514';
  end if;

  delete from public.friendships f
  where (f.user_id = uid and f.friend_id = remove_friend.friend_id)
     or (f.user_id = remove_friend.friend_id and f.friend_id = uid);
end;
$$;


ALTER FUNCTION "public"."remove_friend"("friend_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_guest_answer"("guest_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  guest public.event_guests;
begin
  perform private.require_user();
  select * into guest from public.event_guests g where g.id = remove_guest_answer.guest_id;
  if guest.id is null then
    raise exception using message = 'guest_not_found', detail = 'That guest answer is already gone', errcode = 'PT404';
  end if;
  -- The link row lock serializes with set_guest_availability, so no save lands after the removal.
  -- Link before event, the order set_guest_availability takes them in.
  perform 1 from public.event_guest_links l where l.id = guest.link_id for update;
  -- Organizer or group admin, group not archived.
  perform private.manageable_event(guest.event_id);
  select * into guest from public.event_guests g where g.id = guest.id;
  if guest.removed_at is not null then
    raise exception using message = 'guest_not_found', detail = 'That guest answer is already gone', errcode = 'PT404';
  end if;
  -- Keep the row so the guest's token cannot answer again; the slots go and the seat frees up.
  delete from public.event_guest_availability ga where ga.guest_id = guest.id;
  update public.event_guests g set removed_at = now(), updated_at = now() where g.id = guest.id;
end;
$$;


ALTER FUNCTION "public"."remove_guest_answer"("guest_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_member"("group_id" "uuid", "user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role;
  target_role public.group_role;
begin
  -- Waits for money writes in flight; new ones wait for this transaction.
  -- Membership is read once the lock is held, so a caller removed meanwhile is refused.
  perform 1 from public.groups g where g.id = remove_member.group_id for no key update;
  my_role := private.require_member(remove_member.group_id);

  if remove_member.user_id = auth.uid() then
    raise exception using message = 'use_leave_group', detail = 'Use leave group to remove yourself', errcode = '22023';
  end if;
  if my_role = 'member' then
    raise exception using message = 'not_allowed', detail = 'Only owners and admins can remove members', errcode = '42501';
  end if;

  select m.role into target_role
  from public.group_members m
  where m.group_id = remove_member.group_id and m.user_id = remove_member.user_id;

  if target_role is null then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;
  if target_role = 'owner' then
    raise exception using message = 'cannot_remove_owner', detail = 'The owner cannot be removed', errcode = '42501';
  end if;
  if my_role = 'admin' and target_role <> 'member' then
    raise exception using message = 'not_allowed', detail = 'Admins can only manage regular members', errcode = '42501';
  end if;
  if private.member_balance(remove_member.group_id, remove_member.user_id) <> 0 then
    raise exception using message = 'member_has_balance', detail = 'This member still has an unsettled balance', errcode = '23514';
  end if;

  delete from public.group_members m
  where m.group_id = remove_member.group_id and m.user_id = remove_member.user_id;
end;
$$;


ALTER FUNCTION "public"."remove_member"("group_id" "uuid", "user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_placeholder"("user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  ph public.placeholders;
  my_role public.group_role;
begin
  select * into ph from public.placeholders x where x.profile_id = remove_placeholder.user_id;
  if ph.profile_id is null then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;

  perform 1 from public.groups g where g.id = ph.group_id for no key update;
  my_role := private.require_member(ph.group_id);
  perform private.require_group_open(ph.group_id);

  if not exists (select 1 from public.group_members m where m.group_id = ph.group_id and m.user_id = ph.profile_id) then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;
  if my_role = 'member' and ph.created_by is distinct from uid then
    raise exception using message = 'not_allowed', detail = 'Only admins or whoever added them can remove them', errcode = '42501';
  end if;
  if private.member_balance(ph.group_id, ph.profile_id) <> 0 then
    raise exception using message = 'member_has_balance', detail = 'This member still has an unsettled balance', errcode = '23514';
  end if;

  delete from public.group_members m
  where m.group_id = ph.group_id and m.user_id = ph.profile_id;
end;
$$;


ALTER FUNCTION "public"."remove_placeholder"("user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_availability"("event_id" "uuid", "user_ids" "uuid"[] DEFAULT NULL::"uuid"[]) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  ev public.events := private.member_event(request_availability.event_id);
  targets uuid[];
begin
  perform private.require_group_open(ev.group_id);
  if ev.status <> 'polling' then
    raise exception using message = 'event_not_polling', detail = 'This event is no longer collecting availability', errcode = '23514';
  end if;

  if user_ids is null or cardinality(user_ids) = 0 then
    select coalesce(array_agg(m.user_id order by m.user_id), '{}') into targets
    from public.group_members m
    join public.profiles p on p.id = m.user_id
    where m.group_id = ev.group_id
      and m.user_id <> uid
      and p.deleted_at is null
      and not p.is_placeholder
      and not exists (select 1 from public.availability a where a.event_id = ev.id and a.user_id = m.user_id);
  else
    if exists (
      select 1 from unnest(user_ids) as t (id)
      where not exists (select 1 from public.group_members m where m.group_id = ev.group_id and m.user_id = t.id)
    ) then
      raise exception using message = 'member_not_found', detail = 'Everyone asked must be in the group', errcode = 'PT404';
    end if;
    select coalesce(array_agg(distinct t.id), '{}') into targets
    from unnest(user_ids) as t (id)
    join public.profiles p on p.id = t.id
    where t.id <> uid
      and p.deleted_at is null
      and not p.is_placeholder;
  end if;

  insert into public.availability_requests (event_id, user_id, requested_by, requested_at, responded_at)
  select ev.id, t.id, uid, now(), null
  from unnest(targets) as t (id)
  on conflict (event_id, user_id) do update
    set requested_by = excluded.requested_by,
        requested_at = excluded.requested_at,
        responded_at = null;

  insert into public.notifications (user_id, type, data)
  select t.id, 'availability.requested', jsonb_build_object(
    'event_id', ev.id,
    'group_id', ev.group_id,
    'event_title', ev.title,
    'actor_id', uid
  )
  from unnest(targets) as t (id);

  if cardinality(targets) > 0 then
    perform private.log_activity(ev.group_id, uid, 'availability.requested', ev.id,
      jsonb_build_object('title', ev.title, 'user_ids', to_jsonb(targets)));
  end if;

  return cardinality(targets);
end;
$$;


ALTER FUNCTION "public"."request_availability"("event_id" "uuid", "user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_expense"("id" "uuid") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  gid uuid := (select x.group_id from public.expenses x where x.id = restore_expense.id);
  e public.expenses;
begin
  if gid is not null then
    perform 1 from public.groups g where g.id = gid for share;
    perform private.require_member(gid);
  end if;
  e := private.editable_expense(restore_expense.id);

  if e.deleted_at is null then
    return e;
  end if;

  if exists (
    select s.user_id from public.expense_splits s where s.expense_id = e.id and s.share_cents > 0
    union
    select p.user_id from public.expense_payers p where p.expense_id = e.id
    union
    select e.paid_by
    except
    select m.user_id from public.group_members m where m.group_id = e.group_id
  ) then
    raise exception using message = 'split_member_not_in_group', detail = 'Someone in this expense has left the group', errcode = '23514';
  end if;

  update public.expenses x set deleted_at = null where x.id = e.id returning * into e;
  return e;
end;
$$;


ALTER FUNCTION "public"."restore_expense"("id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."restore_settlement"("id" "uuid") RETURNS "public"."settlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  my_role public.group_role;
  gid uuid;
  s public.settlements;
begin
  select x.group_id into gid from public.settlements x where x.id = restore_settlement.id;
  if gid is null then
    raise exception using message = 'settlement_not_found', detail = 'Payment not found', errcode = 'PT404';
  end if;
  perform 1 from public.groups g where g.id = gid for share;
  my_role := private.require_member(gid);

  select * into s from public.settlements x where x.id = restore_settlement.id for update;
  if s.id is null then
    raise exception using message = 'settlement_not_found', detail = 'Payment not found', errcode = 'PT404';
  end if;
  if my_role = 'member' and uid not in (s.from_user, s.to_user) and uid is distinct from s.created_by then
    raise exception using message = 'not_allowed', detail = 'You can only restore payments you were part of', errcode = '42501';
  end if;
  perform private.require_unarchived(gid);

  if s.deleted_at is not null and (
    select count(*) from public.group_members m
    where m.group_id = gid and m.user_id in (s.from_user, s.to_user)
  ) <> 2 then
    raise exception using message = 'member_not_in_group', detail = 'Someone in this payment has left the group', errcode = '23514';
  end if;

  update public.settlements x set deleted_at = null
  where x.id = s.id
  returning * into s;
  return s;
end;
$$;


ALTER FUNCTION "public"."restore_settlement"("id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."revoke_guest_link"("link_id" "uuid") RETURNS "public"."event_guest_links"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  link public.event_guest_links;
  my_role public.group_role;
begin
  select * into link from public.event_guest_links l where l.id = revoke_guest_link.link_id for update;
  if link.id is null then
    raise exception using message = 'guest_link_not_found', detail = 'This guest link is not valid', errcode = 'PT404';
  end if;
  my_role := private.require_member(link.group_id);
  if my_role = 'member'
     and link.created_by is distinct from uid
     and (select e.created_by from public.events e where e.id = link.event_id) is distinct from uid then
    raise exception using message = 'not_allowed', detail = 'Only whoever made the link, the organizer or a group admin can do that', errcode = '42501';
  end if;
  perform private.require_group_open(link.group_id);

  update public.event_guest_links l set revoked_at = coalesce(l.revoked_at, now())
  where l.id = link.id
  returning * into link;
  return link;
end;
$$;


ALTER FUNCTION "public"."revoke_guest_link"("link_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."schedule_event"("event_id" "uuid", "starts_at" timestamp with time zone) RETURNS "public"."events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  ev public.events := private.manageable_event(schedule_event.event_id);
begin
  if schedule_event.starts_at is null then
    raise exception using message = 'starts_at_required', detail = 'Pick a start time', errcode = '22023';
  end if;
  if ev.status not in ('polling', 'scheduled') then
    raise exception using message = 'event_not_schedulable', detail = 'This event can no longer be scheduled', errcode = '23514';
  end if;

  update public.events e set
    status = 'scheduled',
    starts_at = schedule_event.starts_at,
    ends_at = schedule_event.starts_at + make_interval(mins => e.duration_minutes),
    reminder_sent_at = case
      when e.starts_at is distinct from schedule_event.starts_at then null
      else e.reminder_sent_at
    end
  where e.id = ev.id
  returning * into ev;

  return ev;
end;
$$;


ALTER FUNCTION "public"."schedule_event"("event_id" "uuid", "starts_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_money"("query" "text" DEFAULT NULL::"text", "in_group" "uuid" DEFAULT NULL::"uuid", "person" "uuid" DEFAULT NULL::"uuid", "from_day" "date" DEFAULT NULL::"date", "to_day" "date" DEFAULT NULL::"date", "categories" "text"[] DEFAULT NULL::"text"[], "kinds" "text"[] DEFAULT NULL::"text"[], "before_day" "date" DEFAULT NULL::"date", "before_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "before_id" "uuid" DEFAULT NULL::"uuid", "max_rows" integer DEFAULT 50) RETURNS TABLE("kind" "text", "id" "uuid", "group_id" "uuid", "day" "date", "at" timestamp with time zone, "description" "text", "category" "text", "amount_cents" bigint, "currency" "text", "group_currency" "text", "group_amount_cents" bigint, "paid_by" "uuid", "to_user" "uuid", "created_by" "uuid", "my_paid_cents" bigint, "my_share_cents" bigint, "deleted_at" timestamp with time zone, "matched" "text", "snippet" "text", "payers" "uuid"[], "is_refund" boolean)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  gids uuid[];
  q text := nullif(btrim(coalesce(search_money.query, '')), '');
  pat text;
  amount_text text;
  amounts numeric[];
  tz text;
  lim int := least(greatest(coalesce(search_money.max_rows, 50), 1), 100);
  want_expenses boolean := search_money.kinds is null or 'expense' = any (search_money.kinds);
  want_payments boolean := (search_money.kinds is null or 'payment' = any (search_money.kinds))
    and search_money.categories is null;
begin
  if search_money.in_group is not null then
    perform private.require_member(search_money.in_group);
    gids := array[search_money.in_group];
  else
    gids := array(select private.my_group_ids());
  end if;
  if from_day is not null and to_day is not null and from_day > to_day then
    raise exception using message = 'invalid_date_range', detail = 'The start date is after the end date', errcode = '22023';
  end if;
  if char_length(q) > 200 then
    raise exception using message = 'invalid_query', detail = 'Search for something shorter', errcode = '22023';
  end if;
  if (before_id is null) <> (before_day is null) or (before_id is null) <> (before_at is null) then
    raise exception using message = 'invalid_cursor', detail = 'A page cursor needs a day, a time and an id', errcode = '22023';
  end if;
  tz := private.user_time_zone(uid);

  if q is not null then
    pat := '%' || replace(replace(replace(q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
    -- "12.50", "12,50", "$12.50", "12.50 EUR": an amount in the expense's own currency. Three
    -- digits after the separator also read as thousands ("1,000", "2.500"). A reading only
    -- matches a currency with at least as many minor units as it has decimals.
    if q ~* '^[^0-9a-z]{0,3}\s*[0-9]{1,12}([.,][0-9]{1,3})?\s*([a-z]{3}|[^0-9a-z]{0,3})$' then
      amount_text := substring(q from '[0-9]{1,12}(?:[.,][0-9]{1,3})?');
      amounts := array[replace(amount_text, ',', '.')::numeric];
      if amount_text ~ '[.,][0-9]{3}$' then
        amounts := amounts || translate(amount_text, '.,', '')::numeric;
      end if;
    end if;
  end if;

  return query
  with hits as (
    select e.id, 1 as rank, 'description'::text as matched, null::text as snippet
    from public.expenses e
    where q is not null and e.group_id = any (gids) and e.description ilike pat
    union all
    select e.id, 2, 'notes', e.notes
    from public.expenses e
    where q is not null and e.group_id = any (gids) and e.notes ilike pat
    union all
    select c.expense_id, 3, 'comment', c.body
    from public.comments c
    where q is not null
      and c.group_id = any (gids)
      and c.expense_id is not null
      and c.deleted_at is null
      and c.body ilike pat
    union all
    select x.expense_id, 4, 'person', p.display_name
    from public.expense_payers x
    join public.expenses e on e.id = x.expense_id
    join public.profiles p on p.id = x.user_id
    where q is not null and e.group_id = any (gids) and p.display_name ilike pat
    union all
    select s.expense_id, 4, 'person', p.display_name
    from public.expense_splits s
    join public.expenses e on e.id = s.expense_id
    join public.profiles p on p.id = s.user_id
    where q is not null and e.group_id = any (gids) and p.display_name ilike pat
    union all
    select e.id, 5, 'amount', null
    from public.expenses e
    where amounts is not null
      and e.group_id = any (gids)
      and exists (
        select 1 from unnest(amounts) a
        where scale(a) <= private.minor_units(e.currency::text)
          and e.amount_cents = a * power(10::numeric, private.minor_units(e.currency::text))
      )
  ),
  best as (
    select distinct on (h.id) h.id, h.matched, h.snippet
    from hits h
    order by h.id, h.rank
  ),
  payment_comments as (
    select distinct on (c.settlement_id) c.settlement_id, c.body
    from public.comments c
    where q is not null
      and c.group_id = any (gids)
      and c.settlement_id is not null
      and c.deleted_at is null
      and c.body ilike pat
    order by c.settlement_id, c.created_at, c.id
  ),
  expense_rows as (
    select
      'expense'::text as kind,
      e.id,
      e.group_id,
      e.spent_at as day,
      e.created_at as at,
      e.description,
      e.category,
      e.amount_cents,
      e.currency::text as currency,
      g.currency::text as group_currency,
      private.convert_minor(e.amount_cents, e.fx_rate, e.currency::text, g.currency::text) as group_amount_cents,
      e.paid_by,
      null::uuid as to_user,
      e.created_by,
      e.deleted_at,
      b.matched,
      b.snippet,
      -- Everyone who paid, most first (or who got a refund).
      array(
        select x.user_id from public.expense_payers x
        where x.expense_id = e.id
        order by x.paid_cents desc, x.user_id
      ) as payers,
      e.is_refund
    from public.expenses e
    join public.groups g on g.id = e.group_id
    left join best b on b.id = e.id
    where want_expenses
      and e.group_id = any (gids)
      and (q is null or b.id is not null)
      and e.deleted_at is null
      and (search_money.categories is null or coalesce(e.category, 'other') = any (search_money.categories))
      and (
        search_money.person is null
        or exists (
          select 1 from public.expense_payers x
          where x.expense_id = e.id and x.user_id = search_money.person
        )
        or exists (
          select 1 from public.expense_splits s
          where s.expense_id = e.id and s.user_id = search_money.person
        )
      )
  ),
  payment_rows as (
    select
      'payment'::text as kind,
      st.id,
      st.group_id,
      (st.settled_at at time zone tz)::date as day,
      st.settled_at as at,
      st.note as description,
      null::text as category,
      st.amount_cents,
      st.currency::text as currency,
      g.currency::text as group_currency,
      private.convert_minor(st.amount_cents, st.fx_rate, st.currency::text, g.currency::text) as group_amount_cents,
      st.from_user as paid_by,
      st.to_user,
      st.created_by,
      st.deleted_at,
      case
        when q is null then null
        when st.note ilike pat then 'notes'
        when pc.body is not null then 'comment'
        when pf.display_name ilike pat or pt.display_name ilike pat then 'person'
        when exists (
          select 1 from unnest(amounts) a
          where scale(a) <= private.minor_units(st.currency::text)
            and st.amount_cents = a * power(10::numeric, private.minor_units(st.currency::text))
        ) then 'amount'
      end as matched,
      case
        when q is not null and st.note ilike pat then null
        when pc.body is not null then pc.body
        when q is not null and pf.display_name ilike pat then pf.display_name
        when q is not null and pt.display_name ilike pat then pt.display_name
      end as snippet,
      array[st.from_user] as payers,
      false as is_refund
    from public.settlements st
    join public.groups g on g.id = st.group_id
    join public.profiles pf on pf.id = st.from_user
    join public.profiles pt on pt.id = st.to_user
    left join payment_comments pc on pc.settlement_id = st.id
    where want_payments
      and st.group_id = any (gids)
      and st.deleted_at is null
      and (
        search_money.person is null
        or st.from_user = search_money.person
        or st.to_user = search_money.person
      )
  ),
  page as (
    select u.*
    from (
      select * from expense_rows
      union all
      select * from payment_rows where q is null or payment_rows.matched is not null
    ) u
    where (search_money.from_day is null or u.day >= search_money.from_day)
      and (search_money.to_day is null or u.day <= search_money.to_day)
      and (
        search_money.before_id is null
        or (u.day, u.at, u.id) < (search_money.before_day, search_money.before_at, search_money.before_id)
      )
    order by u.day desc, u.at desc, u.id desc
    limit lim
  )
  select
    pg.kind,
    pg.id,
    pg.group_id,
    pg.day,
    pg.at,
    pg.description,
    pg.category,
    pg.amount_cents,
    pg.currency,
    pg.group_currency,
    pg.group_amount_cents,
    pg.paid_by,
    pg.to_user,
    pg.created_by,
    mine.paid_cents,
    mine.share_cents,
    pg.deleted_at,
    pg.matched,
    pg.snippet,
    pg.payers,
    pg.is_refund
  from page pg
  left join lateral (
    select l.paid_cents, l.share_cents
    from public.expense_ledger l
    where pg.kind = 'expense'
      and l.group_id = pg.group_id
      and l.expense_id = pg.id
      and l.user_id = uid
    -- Keeps this a per-row subquery, so the group and expense ids reach the ledger's window
    -- functions instead of the ledger being computed for every group first.
    offset 0
  ) mine on true
  order by pg.day desc, pg.at desc, pg.id desc;
end;
$_$;


ALTER FUNCTION "public"."search_money"("query" "text", "in_group" "uuid", "person" "uuid", "from_day" "date", "to_day" "date", "categories" "text"[], "kinds" "text"[], "before_day" "date", "before_at" timestamp with time zone, "before_id" "uuid", "max_rows" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."search_money"("query" "text", "in_group" "uuid", "person" "uuid", "from_day" "date", "to_day" "date", "categories" "text"[], "kinds" "text"[], "before_day" "date", "before_at" timestamp with time zone, "before_id" "uuid", "max_rows" integer) IS 'Expenses and payments in the viewer''s groups matching a query and filters, newest first. Page with before_day, before_at, before_id.';



CREATE OR REPLACE FUNCTION "public"."set_availability"("event_id" "uuid", "slots" "jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  ev public.events := private.member_event(set_availability.event_id);
  parsed jsonb;
  saved int;
begin
  perform private.require_group_open(ev.group_id);
  if ev.status <> 'polling' then
    raise exception using message = 'event_not_polling', detail = 'This event is no longer collecting availability', errcode = '23514';
  end if;
  if slots is null or jsonb_typeof(slots) <> 'array' then
    raise exception using message = 'invalid_slots', detail = 'Availability is not valid', errcode = '22023';
  end if;
  if jsonb_array_length(slots) > 5000 then
    raise exception using message = 'invalid_slots', detail = 'Too many slots', errcode = '22023';
  end if;

  begin
    select coalesce(jsonb_agg(jsonb_build_object('slot_start', x.slot_start, 'level', x.level)), '[]'::jsonb)
    into parsed
    from (
      select
        (e.elem ->> 'slot_start')::timestamptz as slot_start,
        coalesce((e.elem ->> 'level')::public.availability_level, 'yes') as level
      from jsonb_array_elements(slots) as e (elem)
    ) x;
  exception
    when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then
      raise exception using message = 'invalid_slots', detail = 'Availability is not valid', errcode = '22023';
  end;

  if exists (
    select 1
    from jsonb_to_recordset(parsed) as s (slot_start timestamptz, level public.availability_level)
    cross join lateral (
      select (s.slot_start at time zone ev.timezone) as local_ts
    ) l
    cross join lateral (
      select
        l.local_ts::date as day,
        (extract(hour from l.local_ts) * 60 + extract(minute from l.local_ts))::int as minute,
        extract(second from l.local_ts) as sec
    ) t
    where s.slot_start is null
       or t.day < ev.window_start
       or t.day > ev.window_end
       or t.sec <> 0
       or t.minute < ev.day_start_minute
       or t.minute + ev.slot_minutes > ev.day_end_minute
       or (t.minute - ev.day_start_minute) % ev.slot_minutes <> 0
  ) then
    raise exception using message = 'invalid_slot', detail = 'Some times are outside this event''s grid', errcode = '22023';
  end if;

  if (select count(*) from jsonb_array_elements(parsed)) <> (
    select count(distinct (s.slot_start))
    from jsonb_to_recordset(parsed) as s (slot_start timestamptz, level public.availability_level)
  ) then
    raise exception using message = 'duplicate_slot', detail = 'A time appears twice', errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(ev.id::text || ':' || uid::text, 0));

  delete from public.availability a
  where a.event_id = ev.id and a.user_id = uid;

  insert into public.availability (event_id, user_id, slot_start, level)
  select ev.id, uid, s.slot_start, s.level
  from jsonb_to_recordset(parsed) as s (slot_start timestamptz, level public.availability_level);

  get diagnostics saved = row_count;

  update public.availability_requests r
  set responded_at = now()
  where r.event_id = ev.id and r.user_id = uid;

  return saved;
end;
$$;


ALTER FUNCTION "public"."set_availability"("event_id" "uuid", "slots" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_default_split"("group_id" "uuid", "split" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  kind public.split_type;
  normalized jsonb;
begin
  perform private.require_member(set_default_split.group_id);
  perform private.require_group_open(set_default_split.group_id);

  if split is null or jsonb_typeof(split) = 'null' then
    update public.groups g set default_split = null where g.id = set_default_split.group_id;
    perform private.log_activity(set_default_split.group_id, uid, 'group.default_split', set_default_split.group_id,
      jsonb_build_object('split_type', null));
    return null;
  end if;

  if jsonb_typeof(split) <> 'object' or jsonb_typeof(split -> 'splits') is distinct from 'array' then
    raise exception using message = 'invalid_splits', detail = 'The split is not valid', errcode = '22023';
  end if;
  begin
    kind := (split ->> 'split_type')::public.split_type;
  exception when invalid_text_representation then
    kind := null;
  end;
  if kind is null or kind not in ('equal', 'percent', 'shares') then
    raise exception using message = 'invalid_splits', detail = 'A default split is equal, by percent or by shares', errcode = '22023';
  end if;

  -- Same validation as an expense (people, duplicates, weights, percent sum).
  select jsonb_agg(
           jsonb_build_object('user_id', c.user_id, 'weight', case when kind = 'equal' then null else c.weight end)
           order by c.user_id)
  into normalized
  from private.compute_splits(10000, kind, split -> 'splits') c;

  if exists (
    select 1 from jsonb_array_elements(normalized) e
    where not exists (
      select 1 from public.group_members m
      where m.group_id = set_default_split.group_id and m.user_id = (e ->> 'user_id')::uuid
    )
  ) then
    raise exception using message = 'split_member_not_in_group', detail = 'Everyone in the split must be in the group', errcode = '23514';
  end if;

  normalized := jsonb_build_object('split_type', kind, 'splits', normalized);
  update public.groups g set default_split = normalized where g.id = set_default_split.group_id;
  perform private.log_activity(set_default_split.group_id, uid, 'group.default_split', set_default_split.group_id,
    jsonb_build_object('split_type', kind));
  return normalized;
end;
$$;


ALTER FUNCTION "public"."set_default_split"("group_id" "uuid", "split" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_guest_availability"("code" "text", "name" "text", "token" "text", "slots" "jsonb") RETURNS TABLE("guest_token" "text", "saved" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  link public.event_guest_links;
  ev public.events;
  grp public.groups;
  me public.event_guests;
  clean_name text := private.clean_guest_name(set_guest_availability.name);
  parsed jsonb;
  fresh_token text;
  n int;
begin
  select * into link from public.event_guest_links l where l.code = set_guest_availability.code for update;
  if link.id is null then
    raise exception using message = 'guest_link_not_found', detail = 'This guest link is not valid', errcode = 'PT404';
  end if;
  select * into ev from public.events e where e.id = link.event_id;
  select * into grp from public.groups g where g.id = link.group_id;

  if link.revoked_at is not null then
    raise exception using message = 'guest_link_revoked', detail = 'This guest link was turned off', errcode = '23514';
  end if;
  if link.expires_at <= now() then
    raise exception using message = 'guest_link_expired', detail = 'This guest link has expired', errcode = '23514';
  end if;
  if grp.archived_at is not null then
    raise exception using message = 'group_archived', detail = 'This group is archived', errcode = '23514';
  end if;
  if ev.status <> 'polling' then
    raise exception using message = 'event_not_polling', detail = 'This event is no longer collecting availability', errcode = '23514';
  end if;
  if char_length(clean_name) not between 1 and 40 then
    raise exception using message = 'invalid_guest_name', detail = 'Names are 1 to 40 characters', errcode = '22023';
  end if;

  parsed := private.event_slots(ev, slots);
  me := private.guest_for_token(link.id, set_guest_availability.token);
  if me.removed_at is not null then
    raise exception using message = 'guest_removed', detail = 'The organizer removed this answer', errcode = '42501';
  end if;

  if me.id is null then
    if jsonb_array_length(parsed) = 0 then
      raise exception using message = 'guest_slots_required', detail = 'Pick at least one time', errcode = '22023';
    end if;
    select count(*)::int into n from public.event_guests g
    where g.link_id = link.id and g.removed_at is null;
    if n >= link.max_guests then
      raise exception using message = 'guest_link_full', detail = 'This guest link is full', errcode = '23514';
    end if;
    if (
      select count(*) from public.event_guests g
      where g.link_id = link.id and g.created_at > now() - interval '10 minutes'
    ) >= 20 then
      raise exception using message = 'guest_rate_limited', detail = 'Too many answers at once, try again in a few minutes', errcode = '23514';
    end if;
    fresh_token := private.random_code(24);
    insert into public.event_guests (link_id, event_id, group_id, display_name, token_hash)
    values (link.id, ev.id, ev.group_id, clean_name, sha256(convert_to(fresh_token, 'UTF8')))
    returning * into me;
  elsif me.saves_window_start > now() - interval '1 hour' then
    if me.saves >= 60 then
      raise exception using message = 'guest_rate_limited', detail = 'Too many saves, try again later', errcode = '23514';
    end if;
    update public.event_guests g
    set saves = g.saves + 1, display_name = clean_name, updated_at = now()
    where g.id = me.id;
  else
    update public.event_guests g
    set saves = 1, saves_window_start = now(), display_name = clean_name, updated_at = now()
    where g.id = me.id;
  end if;

  delete from public.event_guest_availability ga where ga.guest_id = me.id;
  insert into public.event_guest_availability (guest_id, event_id, slot_start, level)
  select me.id, ev.id, s.slot_start, s.level
  from jsonb_to_recordset(parsed) as s (slot_start timestamptz, level public.availability_level);
  get diagnostics n = row_count;

  return query select coalesce(fresh_token, set_guest_availability.token), n;
end;
$$;


ALTER FUNCTION "public"."set_guest_availability"("code" "text", "name" "text", "token" "text", "slots" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_member_role"("group_id" "uuid", "user_id" "uuid", "role" "public"."group_role") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role := private.require_member(set_member_role.group_id);
  target_role public.group_role;
begin
  if my_role = 'member' then
    raise exception using message = 'not_allowed', detail = 'Only owners and admins can change roles', errcode = '42501';
  end if;
  if set_member_role.role = 'owner' then
    raise exception using message = 'use_transfer_ownership', detail = 'Use transfer ownership to make someone the owner', errcode = '22023';
  end if;

  select m.role into target_role
  from public.group_members m
  where m.group_id = set_member_role.group_id and m.user_id = set_member_role.user_id;

  if target_role is null then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;
  if target_role = 'owner' then
    raise exception using message = 'cannot_change_owner', detail = 'The owner''s role cannot be changed', errcode = '42501';
  end if;
  if my_role = 'admin' and target_role <> 'member' then
    raise exception using message = 'not_allowed', detail = 'Admins can only manage regular members', errcode = '42501';
  end if;

  update public.group_members m
  set role = set_member_role.role
  where m.group_id = set_member_role.group_id and m.user_id = set_member_role.user_id;
end;
$$;


ALTER FUNCTION "public"."set_member_role"("group_id" "uuid", "user_id" "uuid", "role" "public"."group_role") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_notification_pref"("category" "text", "push" boolean DEFAULT NULL::boolean, "email" boolean DEFAULT NULL::boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
begin
  if not exists (
    select 1 from private.notification_categories c where c.category = set_notification_pref.category
  ) then
    raise exception using message = 'invalid_notification_category', detail = 'Unknown notification setting', errcode = '22023';
  end if;
  if exists (
    select 1 from private.notification_categories c
    where c.category = set_notification_pref.category and c.required
  ) then
    raise exception using message = 'notification_setting_required', detail = 'Security notices cannot be turned off', errcode = '23514';
  end if;

  insert into public.notification_prefs as p (user_id, category, push, email)
  values (uid, set_notification_pref.category, set_notification_pref.push, set_notification_pref.email)
  on conflict (user_id, category) do update
    set push = coalesce(excluded.push, p.push),
        email = coalesce(excluded.email, p.email);

  -- An email setting changed by hand makes any unsubscribe snapshot stale.
  if set_notification_pref.email is not null then
    delete from private.email_unsubscribe_undo u where u.user_id = uid;
  end if;
end;
$$;


ALTER FUNCTION "public"."set_notification_pref"("category" "text", "push" boolean, "email" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_all"("group_id" "uuid", "settled_on" "date" DEFAULT NULL::"date", "note" "text" DEFAULT NULL::"text") RETURNS SETOF "public"."settlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  v_note text := private.payment_note(settle_all.note);
  v_at timestamptz := private.payment_time(settle_all.settled_on);
  cur text;
  d record;
  paid public.settlements;
begin
  perform 1 from public.groups g where g.id = settle_all.group_id for no key update;
  perform private.require_member(settle_all.group_id);
  perform private.require_unarchived(settle_all.group_id);
  select g.currency into cur from public.groups g where g.id = settle_all.group_id;

  for d in
    select x.from_user, x.to_user, x.amount_cents from private.group_debts(settle_all.group_id) x
    where uid in (x.from_user, x.to_user)
  loop
    -- Nothing may move the balance of someone who left.
    continue when (
      select count(*) from public.group_members m
      where m.group_id = settle_all.group_id and m.user_id in (d.from_user, d.to_user)
    ) <> 2;
    insert into public.settlements (group_id, from_user, to_user, amount_cents, currency, fx_rate, note, settled_at, created_by)
    values (settle_all.group_id, d.from_user, d.to_user, d.amount_cents, cur, 1, v_note, v_at, uid)
    returning * into paid;
    return next paid;
  end loop;
end;
$$;


ALTER FUNCTION "public"."settle_all"("group_id" "uuid", "settled_on" "date", "note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_up"("group_id" "uuid", "to_user" "uuid", "amount_cents" bigint, "currency" "text" DEFAULT NULL::"text", "note" "text" DEFAULT NULL::"text") RETURNS "public"."settlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
#variable_conflict use_column
declare
  uid uuid := auth.uid();
  payer uuid := uid;
  g public.groups;
  cur text;
  fx numeric;
  result public.settlements;
begin
  perform 1 from public.groups x where x.id = settle_up.group_id for share;
  perform private.require_member(settle_up.group_id);
  perform private.require_unarchived(settle_up.group_id);
  select * into g from public.groups x where x.id = settle_up.group_id;

  if settle_up.amount_cents is null or settle_up.amount_cents <= 0 or settle_up.amount_cents > 100000000000 then
    raise exception using message = 'invalid_amount', detail = 'Enter an amount greater than zero', errcode = '22023';
  end if;
  if settle_up.to_user is null or settle_up.to_user = payer then
    raise exception using message = 'invalid_recipient', detail = 'Pick who you paid', errcode = '22023';
  end if;
  if (
    select count(*) from public.group_members m
    where m.group_id = settle_up.group_id and m.user_id in (payer, settle_up.to_user)
  ) <> 2 then
    raise exception using message = 'member_not_found', detail = 'Both people must be in the group', errcode = 'PT404';
  end if;

  cur := upper(coalesce(nullif(btrim(settle_up.currency), ''), g.currency));
  if cur !~ '^[A-Z]{3}$' then
    raise exception using message = 'invalid_currency', detail = 'Unknown currency code', errcode = '22023';
  end if;
  fx := private.fx_rate(cur::char(3), g.currency, current_date);
  if fx is null then
    raise exception using
      message = 'fx_rate_unavailable',
      detail = format('No exchange rate from %s to %s yet', cur, g.currency),
      errcode = '23514';
  end if;

  insert into public.settlements (group_id, from_user, to_user, amount_cents, currency, fx_rate, note, settled_at, created_by)
  values (
    settle_up.group_id, payer, settle_up.to_user, settle_up.amount_cents, cur, fx,
    nullif(btrim(settle_up.note), ''), now(), uid
  )
  returning * into result;

  return result;
end;
$_$;


ALTER FUNCTION "public"."settle_up"("group_id" "uuid", "to_user" "uuid", "amount_cents" bigint, "currency" "text", "note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_up_v2"("group_id" "uuid", "from_user" "uuid", "to_user" "uuid", "amount_cents" bigint, "currency" "text" DEFAULT NULL::"text", "note" "text" DEFAULT NULL::"text", "settled_on" "date" DEFAULT NULL::"date") RETURNS "public"."settlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  my_role public.group_role;
  g public.groups;
  cur text;
  fx numeric;
  result public.settlements;
begin
  perform 1 from public.groups x where x.id = settle_up_v2.group_id for share;
  my_role := private.require_member(settle_up_v2.group_id);
  perform private.require_unarchived(settle_up_v2.group_id);
  select * into g from public.groups x where x.id = settle_up_v2.group_id;

  perform private.check_payment(g.id, my_role, settle_up_v2.from_user, settle_up_v2.to_user, settle_up_v2.amount_cents);
  cur := private.payment_currency(settle_up_v2.currency, g.currency);
  fx := private.payment_fx(cur, g.currency, coalesce(settle_up_v2.settled_on, private.utc_today()));

  insert into public.settlements (group_id, from_user, to_user, amount_cents, currency, fx_rate, note, settled_at, created_by)
  values (
    g.id, settle_up_v2.from_user, settle_up_v2.to_user, settle_up_v2.amount_cents, cur, fx,
    private.payment_note(settle_up_v2.note), private.payment_time(settle_up_v2.settled_on), uid
  )
  returning * into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."settle_up_v2"("group_id" "uuid", "from_user" "uuid", "to_user" "uuid", "amount_cents" bigint, "currency" "text", "note" "text", "settled_on" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."settle_with_friend"("friend_id" "uuid", "settled_on" "date" DEFAULT NULL::"date", "note" "text" DEFAULT NULL::"text", "amounts" "jsonb" DEFAULT NULL::"jsonb") RETURNS SETOF "public"."settlements"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  v_note text := private.payment_note(settle_with_friend.note);
  v_at timestamptz := private.payment_time(settle_with_friend.settled_on);
  picked jsonb := settle_with_friend.amounts;
  gids uuid[];
  gid uuid;
  cur text;
  d record;
  amt bigint;
  matched int := 0;
  paid public.settlements;
begin
  if settle_with_friend.friend_id is null or settle_with_friend.friend_id = uid then
    raise exception using message = 'invalid_parties', detail = 'A payment needs two different people', errcode = '22023';
  end if;
  if picked is not null and (jsonb_typeof(picked) <> 'object' or picked = '{}'::jsonb) then
    raise exception using message = 'invalid_payload', detail = 'Pick at least one group', errcode = '22023';
  end if;

  select coalesce(array_agg(mine.group_id order by mine.group_id), '{}') into gids
  from public.group_members mine
  join public.group_members theirs
    on theirs.group_id = mine.group_id and theirs.user_id = settle_with_friend.friend_id
  where mine.user_id = uid;

  -- Lock order: every group row, in id order, before reading any balance.
  foreach gid in array gids loop
    perform 1 from public.groups g where g.id = gid for no key update;
  end loop;

  foreach gid in array gids loop
    continue when picked is not null and not (picked ? gid::text);
    select g.currency into cur from public.groups g where g.id = gid and g.archived_at is null;
    -- Archived groups are read only; a member may have left before the lock.
    continue when cur is null;
    continue when (
      select count(*) from public.group_members m
      where m.group_id = gid and m.user_id in (uid, settle_with_friend.friend_id)
    ) <> 2;

    for d in
      select x.from_user, x.to_user, x.amount_cents from private.group_debts(gid) x
      where (x.from_user = uid and x.to_user = settle_with_friend.friend_id)
         or (x.from_user = settle_with_friend.friend_id and x.to_user = uid)
    loop
      amt := d.amount_cents;
      if picked is not null then
        begin
          amt := (picked ->> gid::text)::bigint;
        exception
          when invalid_text_representation or numeric_value_out_of_range then
            raise exception using message = 'invalid_payload', detail = 'The amounts are not valid', errcode = '22023';
        end;
        if amt is null or amt <= 0 or amt > d.amount_cents then
          raise exception using message = 'invalid_amount', detail = 'Pay more than zero and no more than is owed', errcode = '22023';
        end if;
        matched := matched + 1;
      end if;
      insert into public.settlements (group_id, from_user, to_user, amount_cents, currency, fx_rate, note, settled_at, created_by)
      values (gid, d.from_user, d.to_user, amt, cur, 1, v_note, v_at, uid)
      returning * into paid;
      return next paid;
    end loop;
  end loop;

  -- A picked group that is not shared, is archived, or has nothing owed any more.
  if picked is not null and matched <> (select count(*) from jsonb_object_keys(picked)) then
    raise exception using message = 'nothing_owed', detail = 'Nothing is owed in one of those groups any more', errcode = '23514';
  end if;
end;
$$;


ALTER FUNCTION "public"."settle_with_friend"("friend_id" "uuid", "settled_on" "date", "note" "text", "amounts" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."simplified_debts"("group_id" "uuid") RETURNS TABLE("from_user" "uuid", "to_user" "uuid", "amount_cents" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  creditors uuid[];
  credits bigint[];
  debtors uuid[];
  debts bigint[];
  ci int;
  di int;
  pay bigint;
begin
  perform private.require_member(simplified_debts.group_id);

  select
    coalesce(array_agg(b.user_id order by b.user_id) filter (where b.net_cents > 0), '{}'),
    coalesce(array_agg(b.net_cents order by b.user_id) filter (where b.net_cents > 0), '{}'),
    coalesce(array_agg(b.user_id order by b.user_id) filter (where b.net_cents < 0), '{}'),
    coalesce(array_agg(-b.net_cents order by b.user_id) filter (where b.net_cents < 0), '{}')
  into creditors, credits, debtors, debts
  from public.group_balances b
  where b.group_id = simplified_debts.group_id;

  loop
    -- Largest remaining creditor and debtor; arrays are in user id order, so
    -- strict > keeps the smallest id on ties.
    ci := null;
    for i in 1 .. coalesce(cardinality(credits), 0) loop
      if credits[i] > 0 and (ci is null or credits[i] > credits[ci]) then
        ci := i;
      end if;
    end loop;

    di := null;
    for i in 1 .. coalesce(cardinality(debts), 0) loop
      if debts[i] > 0 and (di is null or debts[i] > debts[di]) then
        di := i;
      end if;
    end loop;

    exit when ci is null or di is null;

    pay := least(credits[ci], debts[di]);
    credits[ci] := credits[ci] - pay;
    debts[di] := debts[di] - pay;

    from_user := debtors[di];
    to_user := creditors[ci];
    amount_cents := pay;
    return next;
  end loop;
end;
$$;


ALTER FUNCTION "public"."simplified_debts"("group_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."skip_recurring_expense"("id" "uuid") RETURNS "public"."recurring_expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  rid uuid := skip_recurring_expense.id;
  my_role public.group_role;
  gid uuid;
  r public.recurring_expenses;
  result public.recurring_expenses;
begin
  select x.group_id into gid from public.recurring_expenses x where x.id = rid;
  if gid is null then
    raise exception using message = 'recurring_not_found', detail = 'Repeating expense not found', errcode = 'PT404';
  end if;
  perform 1 from public.groups x where x.id = gid for share;
  my_role := private.require_member(gid);
  perform private.require_unarchived(gid);

  select * into r from public.recurring_expenses x where x.id = rid for update;
  if r.id is null then
    raise exception using message = 'recurring_not_found', detail = 'Repeating expense not found', errcode = 'PT404';
  end if;
  if my_role = 'member' and not private.recurring_involves(r.created_by, r.paid_by, r.payers, r.splits, uid) then
    raise exception using message = 'not_allowed', detail = 'Only the people in it or an admin can change it', errcode = '42501';
  end if;

  update public.recurring_expenses x
  set next_run_on = private.recurring_step(r.next_run_on, r.recurrence, private.recurring_anchor_day(r))
  where x.id = r.id
  returning * into result;

  perform private.log_activity(gid, uid, 'recurring.skipped', result.id, jsonb_build_object(
    'description', result.description,
    'amount_cents', result.amount_cents,
    'currency', result.currency,
    'skipped_on', r.next_run_on,
    'next_run_on', result.next_run_on
  ));
  return result;
end;
$$;


ALTER FUNCTION "public"."skip_recurring_expense"("id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."spending_summary"("in_group" "uuid" DEFAULT NULL::"uuid", "from_day" "date" DEFAULT NULL::"date", "to_day" "date" DEFAULT NULL::"date", "in_currency" "text" DEFAULT NULL::"text") RETURNS TABLE("group_id" "uuid", "currency" "text", "month" "date", "category" "text", "expense_count" integer, "spend_cents" bigint, "paid_cents" bigint, "share_cents" bigint, "payments_made_cents" bigint, "payments_received_cents" bigint, "unconverted_count" integer)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
#variable_conflict use_column
declare
  uid uuid := private.require_user();
  gids uuid[];
  tz text;
  target text := upper(nullif(btrim(spending_summary.in_currency), ''));
begin
  if spending_summary.in_group is not null then
    perform private.require_member(spending_summary.in_group);
    gids := array[spending_summary.in_group];
  else
    gids := array(select private.my_group_ids());
  end if;
  if from_day is not null and to_day is not null and from_day > to_day then
    raise exception using message = 'invalid_date_range', detail = 'The start date is after the end date', errcode = '22023';
  end if;
  if target is not null and target !~ '^[A-Z]{3}$' then
    raise exception using message = 'invalid_currency', detail = 'Pick a currency', errcode = '22023';
  end if;
  tz := private.user_time_zone(uid);

  -- With in_currency, every amount (already in its group's currency) is converted once more, at
  -- the rate on or before that expense's date (a payment's day for payments), with the lookup
  -- and rounding expenses use when they are saved, plus private.insights_fx_rate's step through
  -- a common base when two currencies have no rate between them. Amounts with no rate are left
  -- out and counted in unconverted_count.
  return query
  with ledger as (
    select
      l.*,
      row_number() over (partition by l.group_id, l.expense_id order by l.user_id) = 1 as first_line
    from public.expense_ledger l
    where l.group_id = any (gids)
      and (spending_summary.from_day is null or l.spent_at >= spending_summary.from_day)
      and (spending_summary.to_day is null or l.spent_at <= spending_summary.to_day)
  ),
  lines as (
    select
      x.group_id,
      x.currency,
      date_trunc('month', x.spent_at)::date as month,
      coalesce(x.category, 'other') as category,
      x.user_id,
      x.first_line,
      x.total_cents,
      x.paid_cents,
      x.share_cents,
      case
        when target is null or target = x.currency then 1::numeric
        else private.insights_fx_rate(x.currency::char(3), target::char(3), x.spent_at)
      end as rate
    from ledger x
    where x.first_line or x.user_id = uid
  ),
  payments as (
    select
      st.group_id,
      g.currency::text as currency,
      (st.settled_at at time zone tz)::date as day,
      st.from_user,
      st.to_user,
      private.convert_minor(st.amount_cents, st.fx_rate, st.currency::text, g.currency::text) as amount
    from public.settlements st
    join public.groups g on g.id = st.group_id
    where st.group_id = any (gids)
      and st.deleted_at is null
      and (st.from_user = uid or st.to_user = uid)
  ),
  payment_lines as (
    select
      p.*,
      case
        when target is null or target = p.currency then 1::numeric
        else private.insights_fx_rate(p.currency::char(3), target::char(3), p.day)
      end as rate
    from payments p
    where (spending_summary.from_day is null or p.day >= spending_summary.from_day)
      and (spending_summary.to_day is null or p.day <= spending_summary.to_day)
  )
  select
    x.group_id,
    x.currency,
    x.month,
    x.category,
    sum(x.expense_count)::int,
    sum(x.spend_cents)::bigint,
    sum(x.paid_cents)::bigint,
    sum(x.share_cents)::bigint,
    sum(x.payments_made_cents)::bigint,
    sum(x.payments_received_cents)::bigint,
    sum(x.unconverted_count)::int
  from (
    select
      l.group_id,
      coalesce(target, l.currency) as currency,
      l.month,
      l.category,
      -- Converted expenses only; the rest are in unconverted_count.
      count(*) filter (where l.first_line and l.rate is not null) as expense_count,
      coalesce(sum(private.convert_minor(l.total_cents, l.rate, l.currency, coalesce(target, l.currency)))
        filter (where l.first_line and l.rate is not null), 0) as spend_cents,
      coalesce(sum(private.convert_minor(l.paid_cents, l.rate, l.currency, coalesce(target, l.currency)))
        filter (where l.user_id = uid and l.rate is not null), 0) as paid_cents,
      coalesce(sum(private.convert_minor(l.share_cents, l.rate, l.currency, coalesce(target, l.currency)))
        filter (where l.user_id = uid and l.rate is not null), 0) as share_cents,
      0::bigint as payments_made_cents,
      0::bigint as payments_received_cents,
      count(*) filter (where l.first_line and l.rate is null) as unconverted_count
    from lines l
    group by l.group_id, l.currency, l.month, l.category
    union all
    select
      p.group_id,
      coalesce(target, p.currency),
      date_trunc('month', p.day)::date,
      null::text,
      0,
      0,
      0,
      0,
      coalesce(sum(private.convert_minor(p.amount, p.rate, p.currency, coalesce(target, p.currency)))
        filter (where p.from_user = uid and p.rate is not null), 0),
      coalesce(sum(private.convert_minor(p.amount, p.rate, p.currency, coalesce(target, p.currency)))
        filter (where p.to_user = uid and p.rate is not null), 0),
      count(*) filter (where p.rate is null)
    from payment_lines p
    group by p.group_id, p.currency, date_trunc('month', p.day)
  ) x
  group by x.group_id, x.currency, x.month, x.category
  order by x.month, x.group_id, x.category nulls last;
end;
$_$;


ALTER FUNCTION "public"."spending_summary"("in_group" "uuid", "from_day" "date", "to_day" "date", "in_currency" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."spending_summary"("in_group" "uuid", "from_day" "date", "to_day" "date", "in_currency" "text") IS 'The viewer''s spending per group, month and category, in group currency or converted into in_currency at each expense''s date. Payment rows have no category.';



CREATE OR REPLACE FUNCTION "public"."transfer_ownership"("group_id" "uuid", "user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
#variable_conflict use_column
declare
  my_role public.group_role := private.require_member(transfer_ownership.group_id);
  uid uuid := auth.uid();
begin
  if my_role <> 'owner' then
    raise exception using message = 'not_allowed', detail = 'Only the owner can transfer ownership', errcode = '42501';
  end if;
  if transfer_ownership.user_id = uid then
    raise exception using message = 'already_owner', detail = 'You already own this group', errcode = '22023';
  end if;
  if not exists (
    select 1 from public.group_members m
    join public.profiles p on p.id = m.user_id
    where m.group_id = transfer_ownership.group_id
      and m.user_id = transfer_ownership.user_id
      and p.deleted_at is null
  ) then
    raise exception using message = 'member_not_found', detail = 'That person is not in this group', errcode = 'PT404';
  end if;

  -- Demote first: the one-owner unique index is not deferrable.
  update public.group_members m set role = 'admin'
  where m.group_id = transfer_ownership.group_id and m.user_id = uid;

  update public.group_members m set role = 'owner'
  where m.group_id = transfer_ownership.group_id and m.user_id = transfer_ownership.user_id;
end;
$$;


ALTER FUNCTION "public"."transfer_ownership"("group_id" "uuid", "user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_expense"("id" "uuid", "payload" "jsonb") RETURNS "public"."expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if update_expense.id is null then
    raise exception using message = 'expense_not_found', detail = 'Expense not found', errcode = 'PT404';
  end if;
  return private.save_expense(
    update_expense.id,
    coalesce(payload, '{}'::jsonb) - array['payers', 'is_refund', 'items', 'tax_cents', 'tip_cents', 'discount_cents']
  );
end;
$$;


