CREATE POLICY "profiles: update self" ON "public"."profiles" FOR UPDATE TO "authenticated" USING (("id" = ( SELECT "auth"."uid"() AS "uid"))) WITH CHECK (("id" = ( SELECT "auth"."uid"() AS "uid")));



ALTER TABLE "public"."push_tokens" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "push_tokens: create own" ON "public"."push_tokens" FOR INSERT TO "authenticated" WITH CHECK (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



CREATE POLICY "push_tokens: delete own" ON "public"."push_tokens" FOR DELETE TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



CREATE POLICY "push_tokens: read own" ON "public"."push_tokens" FOR SELECT TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



CREATE POLICY "push_tokens: update own" ON "public"."push_tokens" FOR UPDATE TO "authenticated" USING (("user_id" = ( SELECT "auth"."uid"() AS "uid"))) WITH CHECK (("user_id" = ( SELECT "auth"."uid"() AS "uid")));



ALTER TABLE "public"."recurring_expenses" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "recurring_expenses: involved or admin delete" ON "public"."recurring_expenses" FOR DELETE TO "authenticated" USING ((( SELECT "private"."is_group_admin"("recurring_expenses"."group_id") AS "is_group_admin") OR (("group_id" = ANY (ARRAY( SELECT "private"."my_group_ids"() AS "my_group_ids"))) AND "private"."recurring_involves"("created_by", "paid_by", "payers", "splits", ( SELECT "auth"."uid"() AS "uid")))));



CREATE POLICY "recurring_expenses: involved or admin edit" ON "public"."recurring_expenses" FOR UPDATE TO "authenticated" USING ((( SELECT "private"."is_group_admin"("recurring_expenses"."group_id") AS "is_group_admin") OR (("group_id" = ANY (ARRAY( SELECT "private"."my_group_ids"() AS "my_group_ids"))) AND "private"."recurring_involves"("created_by", "paid_by", "payers", "splits", ( SELECT "auth"."uid"() AS "uid"))))) WITH CHECK (((( SELECT "private"."is_group_admin"("recurring_expenses"."group_id") AS "is_group_admin") OR (("group_id" = ANY (ARRAY( SELECT "private"."my_group_ids"() AS "my_group_ids"))) AND "private"."recurring_involves"("created_by", "paid_by", "payers", "splits", ( SELECT "auth"."uid"() AS "uid")))) AND ( SELECT "private"."group_is_open"("recurring_expenses"."group_id") AS "group_is_open")));



CREATE POLICY "recurring_expenses: members read" ON "public"."recurring_expenses" FOR SELECT TO "authenticated" USING (("group_id" = ANY (ARRAY( SELECT "private"."my_group_ids"() AS "my_group_ids"))));



ALTER TABLE "public"."reports" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "reports: create own" ON "public"."reports" FOR INSERT TO "authenticated" WITH CHECK ((("reporter_id" = ( SELECT "auth"."uid"() AS "uid")) AND (("group_id" IS NULL) OR ( SELECT "private"."is_group_member"("reports"."group_id") AS "is_group_member"))));



CREATE POLICY "reports: read own" ON "public"."reports" FOR SELECT TO "authenticated" USING (("reporter_id" = ( SELECT "auth"."uid"() AS "uid")));



ALTER TABLE "public"."settlements" ENABLE ROW LEVEL SECURITY;


CREATE POLICY "settlements: members read" ON "public"."settlements" FOR SELECT TO "authenticated" USING (("group_id" = ANY (ARRAY( SELECT "private"."my_group_ids"() AS "my_group_ids"))));



CREATE POLICY "settlements: two-step sign in done" ON "public"."settlements" AS RESTRICTIVE FOR SELECT TO "authenticated" USING (( SELECT "private"."mfa_satisfied"() AS "mfa_satisfied"));



